19	/// The canonical value list of axis `i` (0..11 in MARKS order), from the kernel.
20	pub fn axis_values(i: usize) -> &'static [IgPrim] {
21	    let mut buf = [0u8; 4];
22	    ordinal_table(MARKS[i % 12].encode_utf8(&mut buf))
23	}
