25	/// Imscribe an ordered IMASM program through the kernel's structural witness.
26	fn imscribe_program(p: &Program) -> IgTuple {
27	    IgTuple::from_snapshot(&self_imscribe(p))
28	}
29	
30	/// A glyph word → its tuple. Order-sensitive: this runs the program. Falls back
31	/// to the byte route only when the word is not a clean mark sequence.
32	pub fn word_to_tuple(word: &str) -> IgTuple {
33	    match program_from_glyphs(word) {
34	        Ok(prog) => imscribe_program(&prog),
35	        Err(_) => bytes_to_tuple(word.as_bytes()),
36	    }
37	}
