39	/// Arbitrary bytes → an ordered program via the canonical mark set → its tuple.
40	pub fn bytes_to_tuple(bytes: &[u8]) -> IgTuple {
41	    let mut p = Program::empty();
42	    for &b in bytes {
43	        let mark = MARKS[(b as usize) % MARKS.len()];
44	        if let Some(g) = Glyph::from_char(mark) {
45	            p.push(glyph_to_token(g));
46	        }
47	    }
48	    imscribe_program(&p)
49	}
