/// Setter mirror of `prim_from_name`, for applying an absorption rule's
/// forced value back onto a result tuple. Unrecognized names are a no-op.
pub fn set_prim_by_name(name: &str, ig: &mut IgTuple, val: IgPrim) {
    match name {
        "≺" => ig.p = val,
        "⊙" => ig.phi = val,
        "⊡" => ig.omega = val,
        "⊥" => ig.h = val,
        "∈" => ig.g = val,
        "⊣" => ig.t = val,
