/// `meet` under an arbitrary dialect's own abs_rules table instead of
/// canonical's — the active ruleset actually shaping the operation, not
/// just describing it.
pub fn meet_under(dialect: u8, a: &IgTuple, b: &IgTuple) -> LatticeResult {
