        let right_hits = crate::dialect::prim_from_name(rule.prim, b) == Some(target);
        let triggered = match rule.direction {
            1 => left_hits,
            2 => right_hits,
            _ => left_hits || right_hits,
        };
        if triggered {
            crate::dialect::set_prim_by_name(rule.prim, result, target);
        }
    }
}

