input.new_string:
    #[test]
    fn test_tensor_stoichiometry_absorption() {
        // ABS_CANONICAL declares up (𐑳) absorbing on S under tensor.
        let mut hung = oinf();
        hung.s = IgPrim::hung;
        let mut up = oinf();
        up.s = IgPrim::up;
        let t = tensor(&hung, &up);
        assert_eq!(t.s, IgPrim::up);
    }

    #[test]
    fn test_tensor_under_dialect_differs_from_canonical() {
        // U67 declares ABS_EP: err (𐑻) absorbs on Phi under every op. Without
        // that rule, ord_max(err, haha) picks haha (haha's ordinal 3.0 beats
        // err's 2.67) — so this pair only diverges between dialects if the
        // dialect's own abs_rules are actually being read, not canonical's
        // hardcoded two rules standing in for whichever dialect is active.
        let mut a = oinf();
        a.phi = IgPrim::err;
        let mut b = oinf();
        b.phi = IgPrim::haha;

        let canonical = tensor_under(0, &a, &b);
        assert_eq!(canonical.phi, IgPrim::haha);

        let under_ep = tensor_under(67, &a, &b);
        assert_eq!(under_ep.phi, IgPrim::err);
    }
}

