/// compute_tier (kernel.rs) is canonical-only — it never reads
/// active_dialect and hardcodes canonical's own Path A/B/R2 logic directly
/// on Snapshot fields, bypassing the IgTuple/gate system this module
/// already runs generically for every one of the 88 dialects. This is that
/// same generalization, applied to tier: dialect 0 returns snap.tier
/// completely unchanged (compute_tier already computed it, so there is
/// nothing to recompute and no risk of drift); any other dialect gets a
/// verdict from its OWN gates and OWN T-constitution via dialect_verdict,
/// mapped onto tier's 0-3 scale by the same reading canonical itself uses —
/// a live paradox (B4::B, gate closed but the ceiling blocked) is not a
/// failure here, it is the richest reading, the same way canonical's own
/// Path A only reaches its top tier through effective_dialetheia. Clean
/// closure (T) ranks below that; N (open gate, ceiling still consistent)
/// carries some structure; F is nothing.
pub fn compute_tier_under(dialect: u8, snap: &crate::kernel::Snapshot) -> u8 {
    if dialect == 0 {
        return snap.tier;
    }
    if (dialect as usize) >= DIALECT_COUNT {
        return 0;
    }
    let ig = IgTuple::from_snapshot(snap);
    let unis = all_dialects();
    match dialect_verdict(&unis[dialect as usize], &ig) {
        B4::B => 3,
        B4::T => 2,
        B4::N => 1,
        B4::F => 0,
    }
}

