232	/// active_dialect and hardcodes canonical's own Path A/B/R2 logic directly
233	/// on Snapshot fields, bypassing the IgTuple/gate system this module
234	/// already runs generically for every one of the 88 dialects. This is that
235	/// same generalization, applied to tier: dialect 0 returns snap.tier
236	/// completely unchanged (compute_tier already computed it, so there is
237	/// nothing to recompute and no risk of drift); any other dialect gets a
238	/// verdict from its OWN gates and OWN T-constitution via dialect_verdict,
239	/// mapped onto tier's 0-3 scale by the same reading canonical itself uses —
240	/// a live paradox (B4::B, gate closed but the ceiling blocked) is not a
241	/// failure here, it is the richest reading, the same way canonical's own
242	/// Path A only reaches its top tier through effective_dialetheia. Clean
243	/// closure (T) ranks below that; N (open gate, ceiling still consistent)
244	/// carries some structure; F is nothing.
245	pub fn compute_tier_under(dialect: u8, snap: &crate::kernel::Snapshot) -> u8 {
246	    if dialect == 0 {
247	        return snap.tier;
248	    }
249	    if (dialect as usize) >= DIALECT_COUNT {
250	        return 0;
251	    }
252	    let ig = IgTuple::from_snapshot(snap);
253	    let unis = all_dialects();
