393	fn lift_file(path: &str) -> i32 {
394	    let raw = match std::fs::read(path) {
395	        Ok(r) => r,
396	        Err(e) => { eprintln!("cannot read {}: {}", path, e); return 2; }
397	    };
398	    let l = loader::load(&raw);
399	    if l.code.is_empty() {
400	        eprintln!("{}: no executable sections found", path);
401	        return 1;
402	    }
403	    if l.arch != "x86-64" && l.arch != "x86-32" {
404	        eprintln!("{}: {} {} code. V⊙x decodes x86; it will not misread another", path, l.format, l.arch);
405	        eprintln!("architecture and hand back a confident, wrong word.");
406	        return 3;
407	    }
408	    if l.arch == "x86-32" {
409	        return audit_linear(path, &l, 32);
410	    }
411	    let image = vox_decode::Image { segments: l.code };
412	    println!("{}  {}  entry 0x{:x}  {} byte(s) of code", path, l.format, l.entry, image.total_bytes());
413	    let mut seeds: Vec<u64> = l.symbols.values().copied().collect(); seeds.push(l.entry);
414	    let w = vox_decode::walk(&image, l.entry, &seeds);
415	    let decoded: usize = w.functions.iter().map(|f| f.1.len()).sum();
416	    println!("  {} function(s), {} instruction(s)", w.functions.len(), decoded);
417	    println!("  claimed {}% of the image ({} of {} bytes)",
418	        w.claimed_percent(), w.claimed_bytes, w.total_bytes);
419	
420	    let mut tally = [0usize; 4]; // T B N F
421	    let mut illtyped: Vec<(u64, String)> = Vec::new();
422	    let mut descent_f = 0usize;
423	    // recursive-descent functions: the trustworthy set
424	    let mut claimed: std::collections::BTreeSet<u64> = std::collections::BTreeSet::new();
425	    for (start, f) in &w.functions {
426	        for ins in f { claimed.insert(ins.address); }
427	        let word = vox::recompile_function(f);
428	        match vox::verdict(&word) {
429	            'T' => tally[0] += 1, 'B' => tally[1] += 1, 'N' => tally[2] += 1,
430	            _ => { tally[3] += 1; descent_f += 1; if illtyped.len() < 8 { illtyped.push((*start, vox::glyphs(&word))); } }
431	        }
432	    }
433	    let descended = w.functions.len();
434	    // fallback sweep: linear-decode what descent never reached, group into
435	    // functions of their own at each terminal, and verdict those too.
