/// Add two numbers by walking their own words bit by bit with a carried
/// carry, least-significant first, exactly as subtract_via_word walks a
/// borrow. Each step reads three bits (a's, b's, the incoming carry) and
/// produces a result bit and an outgoing carry, the same three-input truth
/// table a hardware full adder uses -- there is no `+` anywhere in this
/// function. A carry surviving past the last bit becomes one final extra
/// bit block, exactly the way grade-school addition writes a new leading
/// digit when the last column overflows.
pub fn add_via_word(a: &BigUint, b: &BigUint) -> BigUint {
    let bits_a = word_bits(a);
    let bits_b = word_bits(b);
    let n = bits_a.len().max(bits_b.len());
    let mut result = alloc::vec::Vec::with_capacity(n + 1);
    let mut carry = false;
    for i in 0..n {
        let x = *bits_a.get(i).unwrap_or(&false);
        let y = *bits_b.get(i).unwrap_or(&false);
        let (sum, carry_out) = match (x, y, carry) {
            (false, false, false) => (false, false),
            (false, false, true)  => (true,  false),
            (false, true,  false) => (true,  false),
            (false, true,  true)  => (false, true),
            (true,  false, false) => (true,  false),
            (true,  false, true)  => (false, true),
            (true,  true,  false) => (false, true),
            (true,  true,  true)  => (true,  true),
        };
        result.push(sum);
        carry = carry_out;
    }
    if carry { result.push(true); }
    bits_to_value(&result)
}

