/// Divide and take the remainder together, by the standard long-division
/// shape: walk a's own bit blocks from the most significant down, doubling
/// a running remainder at each step to shift in the next dividend bit
/// (double_via_word, plus add_via_word to bring that bit in when it's
/// set), and wherever the remainder has grown at least as large as m,
/// subtract m back out (subtract_via_word) and mark that quotient bit.
/// The only thing here that isn't one of the four proven word operations
/// is the size comparison deciding whether to subtract, the same
/// boundary belnap_gcd already draws with its own `a > b`. None for m=0.
pub fn divmod_via_word(a: &BigUint, m: &BigUint) -> Option<(BigUint, BigUint)> {
    if m.is_zero() { return None; }
    let bits_a = word_bits(a);
    let mut remainder = BigUint::zero();
    let mut quotient_bits = alloc::vec![false; bits_a.len()];
    let one = BigUint::from(1u32);
    for i in (0..bits_a.len()).rev() {
        remainder = double_via_word(&remainder);
        if bits_a[i] {
            remainder = add_via_word(&remainder, &one);
        }
        if remainder >= *m {
            remainder = subtract_via_word(&remainder, m).unwrap();
            quotient_bits[i] = true;
        }
    }
    Some((bits_to_value(&quotient_bits), remainder))
}

/// The remainder half of divmod_via_word, for callers that only need that.
pub fn modulo_via_word(a: &BigUint, m: &BigUint) -> Option<BigUint> {
    divmod_via_word(a, m).map(|(_, r)| r)
}

