fn mod_pow_walk(base: &BigUint, exp_bits: &[bool], modulus: &BigUint) -> BigUint {
    // Every multiply-and-reduce here is now multiply_via_word followed by
    // modulo_via_word, the two proven word operations, in place of `*` and
    // `%`. modulus is never zero at any real call site (n >= 2 is already
    // checked before this function runs), so the unwrap is a proven
    // invariant, the same convention every other word operation here uses.
    let mut result = BigUint::from(1u32);
    let mut b = modulo_via_word(base, modulus).unwrap();
    for &bit in exp_bits {
        if bit {
            result = modulo_via_word(&multiply_via_word(&result, &b), modulus).unwrap();
        }
        b = modulo_via_word(&multiply_via_word(&b, &b), modulus).unwrap();
    }
    result
}

