/// no bit anywhere else has to move. `decode` on what's left is n/2. There
/// is no `/` or `%` in this function; the division already happened in the
/// word's own layout, this only reads it off. None for odd n, since this
/// method has nothing to drop that stays exact.
pub fn halve_even_by_word(n: &BigUint) -> Option<BigUint> {
    let word = encode(&n.to_string());
    let c: alloc::vec::Vec<char> = word.chars().collect();
    if c.len() == 4 && c[1] == '⊙' {
        return Some(BigUint::zero()); // 0's own half is 0
    }
    if c.len() < 9 || c[4] != '⊤' {
        return None; // too short to be a real word, or n is odd
    }
    let mut rest = alloc::string::String::new();
    rest.push(c[0]); // ⊢
    for ch in &c[6..] { rest.push(*ch); } // everything after the dropped block
    decode(&rest)
}

/// n's own bit blocks, least-significant first, read from its word's
/// characters rather than computed by division. Empty for zero.
fn word_bits(n: &BigUint) -> alloc::vec::Vec<bool> {
    let word = encode(&n.to_string());
    let c: alloc::vec::Vec<char> = word.chars().collect();
    if c.len() == 4 { return alloc::vec::Vec::new(); }
    let body = &c[1..c.len() - 3];
    body.chunks(5).map(|cell| cell[3] == '⊥').collect()
