/// operation -- the whole long-division walk runs in bit form and only
/// touches BigUint once, on the way out. None for m=0.
pub fn divmod_via_word(a: &BigUint, m: &BigUint) -> Option<(BigUint, BigUint)> {
    if m.is_zero() { return None; }
