// ═══════════════════════════════════════════════════════════════════════
// The bits_* functions below are the real core: every one takes and
// returns Vec<bool> (a word's own bits, least-significant first), and none
// of them ever touches BigUint. A computation built from these -- gcd,
// modular exponentiation, anything -- can run its entire loop without
// converting back and forth at each step; only the outermost call needs to
// enter and leave bit form at all. The pub fn wrappers below them are the
// BigUint-facing convenience layer: encode once on the way in, decode once
// on the way out, never in between.
// ═══════════════════════════════════════════════════════════════════════

/// Halve, on bits alone: the low bit is the parity, so halving is just
/// dropping it. None if it's set (odd) -- there is nothing here to divide,
/// only a bit to read and discard.
fn bits_halve(bits: &[bool]) -> Option<alloc::vec::Vec<bool>> {
    match bits.first() {
        None => Some(alloc::vec::Vec::new()), // zero halves to zero
        Some(true) => None,                    // odd
        Some(false) => Some(bits[1..].to_vec()),
    }
}

/// Double, on bits alone: insert one new low bit reading 0. Every existing
/// bit is already correct where it sits; prepending shifts everything up
/// one place for free.
fn bits_double(bits: &[bool]) -> alloc::vec::Vec<bool> {
    let mut out = alloc::vec::Vec::with_capacity(bits.len() + 1);
    out.push(false);
    out.extend_from_slice(bits);
    out
}

/// a - b, on bits alone, via the same three-input borrow truth table a
/// hardware subtractor uses. None if a < b, since a borrow surviving past
/// the last bit means the true answer is negative.
fn bits_subtract(a: &[bool], b: &[bool]) -> Option<alloc::vec::Vec<bool>> {
    let n = a.len().max(b.len());
    let mut result = alloc::vec::Vec::with_capacity(n);
    let mut borrow = false;
    for i in 0..n {
        let x = *a.get(i).unwrap_or(&false);
        let y = *b.get(i).unwrap_or(&false);
        let (diff, borrow_out) = match (x, y, borrow) {
            (false, false, false) => (false, false),
            (false, false, true)  => (true,  true),
            (false, true,  false) => (true,  true),
            (false, true,  true)  => (false, true),
            (true,  false, false) => (true,  false),
            (true,  false, true)  => (false, false),
            (true,  true,  false) => (false, false),
            (true,  true,  true)  => (true,  true),
        };
        result.push(diff);
        borrow = borrow_out;
    }
    if borrow { return None; }
    Some(result)
}

/// a + b, on bits alone, via the three-input carry truth table a hardware
/// full adder uses. A carry surviving past the last bit becomes one new
/// leading bit, the same way grade-school addition writes a new digit
/// when the last column overflows.
fn bits_add(a: &[bool], b: &[bool]) -> alloc::vec::Vec<bool> {
    let n = a.len().max(b.len());
    let mut result = alloc::vec::Vec::with_capacity(n + 1);
    let mut carry = false;
    for i in 0..n {
        let x = *a.get(i).unwrap_or(&false);
        let y = *b.get(i).unwrap_or(&false);
        let (sum, carry_out) = match (x, y, carry) {
            (false, false, false) => (false, false),
            (false, false, true)  => (true,  false),
            (false, true,  false) => (true,  false),
            (false, true,  true)  => (false, true),
            (true,  false, false) => (true,  false),
            (true,  false, true)  => (false, true),
            (true,  true,  false) => (false, true),
            (true,  true,  true)  => (true,  true),
        };
        result.push(sum);
        carry = carry_out;
    }
    if carry { result.push(true); }
    result
}

/// a >= b, on bits alone, most significant first (walking the low-first
/// vector backward). A position missing on the shorter side reads as 0.
/// Ordering isn't one of the four arithmetic operations and this is the
/// one place any comparison happens in the operations below -- a direct
/// bit compare, not a BigUint `>=` in disguise.
fn bits_ge(a: &[bool], b: &[bool]) -> bool {
    let n = a.len().max(b.len());
    for i in (0..n).rev() {
        let x = *a.get(i).unwrap_or(&false);
        let y = *b.get(i).unwrap_or(&false);
        if x != y { return x; }
    }
    true
}

/// a * b, on bits alone, shift-and-add: walk b's bits low to high, add in
/// a's current running double wherever the bit is set, doubling either
/// way. The whole computation stays in bit form; nothing here is a
/// BigUint multiply, only repeated bits_add and bits_double.
fn bits_multiply(a: &[bool], b: &[bool]) -> alloc::vec::Vec<bool> {
    let mut acc: alloc::vec::Vec<bool> = alloc::vec::Vec::new();
    let mut shifted = a.to_vec();
    for &bit in b {
        if bit { acc = bits_add(&acc, &shifted); }
        shifted = bits_double(&shifted);
    }
    acc
}

/// a divided by m and the remainder, on bits alone, by long division: walk
/// a's bits from the top down, double the running remainder to shift in
/// the next dividend bit, and subtract m back out (marking that quotient
/// bit) wherever the remainder has grown at least as large as m. The whole
/// walk stays in bit form; only the caller decides whether and when to
/// turn either result back into a BigUint.
fn bits_divmod(a: &[bool], m: &[bool]) -> (alloc::vec::Vec<bool>, alloc::vec::Vec<bool>) {
    let mut remainder: alloc::vec::Vec<bool> = alloc::vec::Vec::new();
    let mut quotient_bits = alloc::vec![false; a.len()];
    for i in (0..a.len()).rev() {
        remainder = bits_double(&remainder);
        if a[i] {
            remainder = bits_add(&remainder, &[true]);
        }
        if bits_ge(&remainder, m) {
            remainder = bits_subtract(&remainder, m).unwrap();
            quotient_bits[i] = true;
        }
    }
    (quotient_bits, remainder)
}

// ═══════════════════════════════════════════════════════════════════════
// BigUint-facing wrappers: encode in once, decode out once.
// ═══════════════════════════════════════════════════════════════════════

/// Halve an even number, reading the result off its own word rather than
/// dividing. None for odd n. See bits_halve for the real operation; this
/// is just its BigUint entry and exit.
pub fn halve_even_by_word(n: &BigUint) -> Option<BigUint> {
    bits_halve(&word_bits(n)).map(|b| bits_to_value(&b))
}

/// n's own bit blocks, least-significant first, read from its word's
/// characters rather than computed by division. Empty for zero.
fn word_bits(n: &BigUint) -> alloc::vec::Vec<bool> {
    let word = encode_biguint(n);
    let c: alloc::vec::Vec<char> = word.chars().collect();
    if c.len() == 4 { return alloc::vec::Vec::new(); }
    let body = &c[1..c.len() - 3];
    body.chunks(5).map(|cell| cell[3] == '⊥').collect()
}

/// n's own parity, read off the first bit block of its word rather than a
/// remainder. No block at all (zero's word) reads as even.
fn is_odd_by_word(n: &BigUint) -> bool {
    bits_is_odd(&word_bits(n))
}

fn bits_is_odd(bits: &[bool]) -> bool {
    bits.first().copied().unwrap_or(false)
}

/// Double a number, reading the result off its own word rather than
/// multiplying. See bits_double for the real operation.
pub fn double_via_word(n: &BigUint) -> BigUint {
    bits_to_value(&bits_double(&word_bits(n)))
}

/// Build the word a sequence of bits (least-significant first) would have
/// under encode, and decode it -- the one BigUint-exit point every
/// bits_* result passes through.
fn bits_to_value(bits: &[bool]) -> BigUint {
    if bits.is_empty() { return BigUint::zero(); }
    let mut word = alloc::string::String::new();
    word.push('⊢');
    for &bit in bits {
        word.push('≻'); word.push('⋈'); word.push('∈');
        word.push(if bit { '⊥' } else { '⊤' });
        word.push('∋');
    }
    word.push('⊙'); word.push('⊡'); word.push('⊣');
    decode(&word).unwrap_or_else(BigUint::zero)
}

/// Subtract two numbers, reading the result off their own words. See
/// bits_subtract for the real operation. None if a < b.
pub fn subtract_via_word(a: &BigUint, b: &BigUint) -> Option<BigUint> {
    bits_subtract(&word_bits(a), &word_bits(b)).map(|r| bits_to_value(&r))
}

/// Add two numbers, reading the result off their own words. See bits_add
/// for the real operation.
pub fn add_via_word(a: &BigUint, b: &BigUint) -> BigUint {
    bits_to_value(&bits_add(&word_bits(a), &word_bits(b)))
}

/// Multiply two numbers, reading the result off their own words. See
/// bits_multiply for the real operation -- the whole shift-and-add walk
/// runs in bit form and only touches BigUint once, on the way out.
pub fn multiply_via_word(a: &BigUint, b: &BigUint) -> BigUint {
    bits_to_value(&bits_multiply(&word_bits(a), &word_bits(b)))
}

/// Divide and take the remainder together. See bits_divmod for the real
/// operation -- the whole long-division walk runs in bit form and only
/// touches BigUint once, on the way out. None for m=0.
pub fn divmod_via_word(a: &BigUint, m: &BigUint) -> Option<(BigUint, BigUint)> {
    if m.is_zero() { return None; }
    let (q, r) = bits_divmod(&word_bits(a), &word_bits(m));
    Some((bits_to_value(&q), bits_to_value(&r)))
}

/// The remainder half of divmod_via_word, for callers that only need that.
pub fn modulo_via_word(a: &BigUint, m: &BigUint) -> Option<BigUint> {
    divmod_via_word(a, m).map(|(_, r)| r)
}

