/// Bit i of a limb vector, least-significant first, 0 past the end.
fn limb_bit(limbs: &[u64], i: usize) -> bool {
    limbs.get(i / 64).map(|l| (l >> (i % 64)) & 1 == 1).unwrap_or(false)
