/// Integer square root by Newton's method, BigUint -- same shape as `isqrt`.
fn isqrt_big(n: &BigUint) -> BigUint {
    if n.is_zero() { return BigUint::zero(); }
    let two = BigUint::from(2u32);
    let mut x = n.clone();
    let mut y = (&x + BigUint::one()) / &two;
    while y < x {
        x = y;
        y = (&x + n / &x) / &two;
    }
    x
