    // directly, checked here rather than trusted from the recursion alone.
    if crate::native_numeral::modulo_via_word(&crate::native_numeral::multiply_via_word(a, &inv), m).unwrap()
        == BigUint::one()
    {
        Some(inv)
    } else {
        None
    }
}

