110	/// Leap steps the search takes before giving a base up. This is a TIME budget,
111	/// not a memory one: the leaping search holds only the two leapers, no table, so
112	/// nothing grows with the winding. A meeting arrives in about sqrt(order) leaps,
113	/// so this reach covers orders up to roughly its square.
114	const LEAP_STEPS: u64 = 80_000_000;
115	
116	/// Number of precomputed jumps the leaper draws from. The leap taken at a point
117	/// is chosen by that point, so the walk is a deterministic function and two
118	/// leapers on it must eventually meet.
119	const LEAP_BUCKETS: usize = 32;
120	
121	/// A positive multiple of the multiplicative order of `a` modulo `n`, found by
122	/// the table-free leaping search of the ob3ect `table_free_winding_by_leaping`
123	/// (word ⊢∈≻⋈≻⋈⊥⋈≻⋈≻⋈⊤⊞≺⊡∋⊙⊣). The loop is the ring `a` generates. ∈ sets two
124	/// leapers on it. ≻ is a leap of LARGE pseudo-random distance drawn from the
125	/// current point, x -> x·a^{s(x)}, not a small stride; ⋈ accumulates the leap
126	/// distance into each leaper's exponent. ⊥ is the drift while they have not met;
127	/// ⊤ is the meeting x_slow = x_fast; ⊞ holds the meeting where the two carry
128	/// different accumulated distances at the same point; ≺ takes their difference,
129	/// which the closed loop makes a whole multiple of the winding; ⊡ fixes it.
130	///
131	/// The large jump is the load-bearing part: leaps that wander the whole loop
132	/// meet by the birthday count in about sqrt(order) steps, where a small uniform
133	/// stride would only drift and take a full order to return. Memory is the two
134	/// leapers and the precomputed jumps, nothing that grows with the order, so
135	/// there is no table and no cap on reach beyond the leap-step time budget.
136	fn order_multiple_leaping(a: &BigUint, n: &BigUint, steps: u64) -> Option<BigUint> {
137	    use alloc::vec::Vec;
138	    let one = BigUint::one();
139	    let a = a % n;
140	    if a == one { return Some(one); }
141	    // Small pre-walk catches a tiny order directly.
142	    let mut v = one.clone();
143	    for k in 1..=64u64 {
144	        v = (&v * &a) % n;
145	        if v == one { return Some(BigUint::from(k)); }
146	    }
147	
148	    // The jumps: LARGE pseudo-random exponents s_i, as group elements a^{s_i}.
149	    // A step at point x multiplies by the jump its low word selects, and adds
150	    // that jump's exponent to the leaper's accumulated distance.
151	    let mut jexp: Vec<u64> = Vec::with_capacity(LEAP_BUCKETS);
152	    let mut jump: Vec<BigUint> = Vec::with_capacity(LEAP_BUCKETS);
153	    let mut seed: u64 = 0x2545F4914F6CDD1D;
154	    for _ in 0..LEAP_BUCKETS {
155	        seed ^= seed << 13; seed ^= seed >> 7; seed ^= seed << 17; // xorshift
156	        let s = (seed >> 1) | 1; // a large odd exponent
157	        jexp.push(s);
158	        jump.push(a.modpow(&BigUint::from(s), n));
159	    }
160	    let bucket = |x: &BigUint| -> usize {
161	        (x.to_u64_digits().first().copied().unwrap_or(0) as usize) % LEAP_BUCKETS
162	    };
163	
164	    let (mut tx, mut te) = (a.clone(), one.clone());      // slow leaper
165	    let (mut hx, mut he) = (a.clone(), one.clone());      // fast leaper
166	    let mut moved = 0u64;
167	    while moved < steps {
168	        let bt = bucket(&tx);
169	        tx = (&tx * &jump[bt]) % n; te += BigUint::from(jexp[bt]);
170	        for _ in 0..2 {
171	            let bh = bucket(&hx);
172	            hx = (&hx * &jump[bh]) % n; he += BigUint::from(jexp[bh]);
173	        }
174	        moved += 1;
175	        if tx == hx {
176	            let d = if te > he { &te - &he } else { &he - &te };
177	            if d > BigUint::zero() { return Some(d); }
178	            break; // degenerate, no usable difference
179	        }
180	    }
181	    None
182	}
