193	/// The cuts at which the ring's landing register is a clean `T`, read live
194	/// from `cycle_landings`. For the canonical word this is the single cut led
195	/// by the winding fixation ⊡; returning the list, not a hardcoded index,
196	/// keeps the certificate a measurement rather than a memory.
197	fn commit_cuts(word: &str) -> alloc::vec::Vec<usize> {
198	    match cycle_landings(word) {
199	        Some(landings) => landings
200	            .iter()
201	            .enumerate()
202	            .filter(|(_, r)| r.as_str() == "T")
203	            .map(|(k, _)| k)
204	            .collect(),
205	        None => alloc::vec::Vec::new(),
206	    }
207	}
