209	/// The glyph the cut k opens on, for naming which mark commits.
210	fn mark_at(word: &str, k: usize) -> Option<char> {
211	    let chars: alloc::vec::Vec<char> = word.chars().collect();
212	    if chars.is_empty() { return None; }
213	    Some(chars[k % chars.len()])
214	}
