238	/// The certificate the tool exists to speak: the word commits at exactly the
239	/// winding fixation and nowhere else, read from the live orbit.
240	pub fn cert() -> String {
241	    let mut o = String::new();
242	    o.push_str(&format!("word   : {}   period {}\n", WORD, PERIOD));
243	    let cuts = commit_cuts(WORD);
244	    if cuts.is_empty() {
245	        o.push_str("  no clean-T commit cut on this word\n");
246	        return o;
247	    }
248	    o.push_str("  winding-commit cut(s) (register lands clean T):\n");
249	    for k in cuts.iter() {
250	        match mark_at(WORD, *k) {
251	            Some(g) => o.push_str(&format!("    k = {:>2}   led by {}\n", k, g)),
252	            None => o.push_str(&format!("    k = {:>2}\n", k)),
253	        }
254	    }
255	    let single_at_commit = cuts.len() == 1 && mark_at(WORD, cuts[0]) == Some(COMMIT_MARK);
256	    if single_at_commit {
257	        o.push_str("  ONE commit, at the winding fixation ⊡ — the cluster_propagation event.\n");
258	        o.push_str("  Every other cut lands tf: the two poles held, not yet committed.");
259	    } else {
260	        o.push_str("  commit is not isolated to ⊡ on this word.");
261	    }
262	    o
263	}
