265	/// The trilattice reading of the number itself: its digit word and where that
266	/// word comes to rest. The number enters the Grammar the same way
267	/// `prime_winding` reads it, by digit encoding; this is that reading, not a
268	/// factoring claim.
269	pub fn read(n: &str) -> String {
270	    let dw = digit_encode(n);
271	    if dw.is_empty() {
272	        return format!("trilattice_factor read {}: not a valid non-negative integer", n);
273	    }
274	    let landings = cycle_landings(&dw);
275	    let mut o = format!("trilattice_factor read {}:\n", n);
276	    o.push_str(&format!("  hex-digit word   : {}\n", dw));
277	    match landings {
278	        Some(l) => {
279	            let commits = l.iter().filter(|r| r.as_str() == "T").count();
280	            o.push_str(&format!(
281	                "  period {}, {} winding-commit cut(s) over the orbit\n",
282	                l.len(), commits
283	            ));
284	        }
285	        None => o.push_str("  no IMASM glyphs in the digit word\n"),
286	    }
287	    // The native parity-graded word: bijective with n, where the hex word is
288	    // not. This is the mapping the Native IMASM-Numeral Mapping ob3ect gives.
289	    let nw = native_encode(n);
290	    o.push_str(&format!("  native word      : {}\n", nw));
291	    // DIALECT_REGISTER: n's own tuple checked against the 12 dialects whose
292	    // gate-pass sequence reaches the true order where parity alone can fall
293	    // short (see module doc comment). One bit per dialect, PASS/FAIL on n's
294	    // own word, not on a residue cycle — the register `dialect-probe` sweeps
295	    // for order-finding, read here on n directly.
296	    let ig = crate::axis_values::word_to_tuple(&nw);
297	    o.push_str("  dialect register : ");
298	    for &u in DIALECT_REGISTER.iter() {
299	        o.push_str(if crate::repl::dialect_all_pass(u, &ig) { "1" } else { "0" });
300	    }
301	    o.push_str(&format!("  (U{:?})", DIALECT_REGISTER));
302	    o
303	}
