305	/// The winding route: read the factor straight off a winding, the way the ⊡
306	/// commit names, at arbitrary precision. For a base a coprime to n, the
307	/// multiplicative order r is the period of the ring a generates under
308	/// multiplication mod n, the ROTAT period, carrying the full residue at every
309	/// step. When r is even and a^(r/2) is not -1, gcd(a^(r/2) ± 1, n) splits n.
310	/// This is Shor's classical core, native to the SIC-phase structure, the factor
311	/// read from the winding rather than from a rho search. There is no size bound
312	/// on n; the only ceiling is how many steps the order search spends per base
313	/// (`ORDER_STEP_BUDGET`), since finding an order classically is an O(order)
314	/// walk. A base whose order does not close in budget is given up, and if no
315	/// base closes, the number is handed to the rho search, which reaches factors
316	/// without needing the order at all.
317	pub fn winding(n: &str, a_opt: Option<u64>) -> String {
318	    let t = n.trim();
319	    let nv: BigUint = match t.parse() {
320	        Ok(v) => v,
321	        Err(_) => return format!("trilattice_factor winding {}: not a non-negative integer", n),
322	    };
323	    let two = BigUint::from(2u32);
324	    if nv < two {
325	        return format!("trilattice_factor winding {}: n < 2, no winding", n);
326	    }
327	    if (&nv % &two).is_zero() {
328	        return format!(
329	            "trilattice_factor winding {}: {} = 2 × {}   (even, split before any winding)",
330	            n, nv, &nv / &two
331	        );
332	    }
333	
334	    let bases: alloc::vec::Vec<BigUint> = match a_opt {
335	        Some(a) => alloc::vec![BigUint::from(a)],
336	        None => WINDING_BASES.iter().map(|&a| BigUint::from(a)).collect(),
337	    };
338	
339	    let one = BigUint::one();
340	    let mut o = format!("trilattice_factor winding {}:\n", n);
341	    let mut budget_hit = false;
342	    for a in bases.iter() {
343	        let a = a % &nv;
344	        if a < two { continue; }
345	        let g = big_gcd(a.clone(), nv.clone());
346	        if g > one {
347	            o.push_str(&format!(
348	                "  base {} shares a factor: gcd = {} → {} = {} × {}",
349	                a, g, nv, g, &nv / &g
350	            ));
351	            return o;
352	        }
353	        let d = match order_multiple_leaping(&a, &nv, LEAP_STEPS) {
354	            Some(d) => d,
355	            None => { budget_hit = true; continue; }
356	        };
357	        // d is a multiple of the order (a crossing gives a^{d} = 1). Halve while
358	        // a^{d/2} = 1, keeping it a multiple, until a^{d/2} is a nontrivial
359	        // square root of 1 that splits n.
360	        let mut r = d.clone();
361	        while (&r % &two).is_zero() {
362	            let half = &r / &two;
363	            let a_half = a.modpow(&half, &nv);
364	            if a_half == one { r = half; continue; }   // still a multiple, reduce
365	            if a_half == &nv - &one { break; }          // trivial root, this base fails
366	            let p = big_gcd(&a_half - &one, nv.clone());
367	            let q = big_gcd(&a_half + &one, nv.clone());
368	            let nontrivial = p > one && q > one && p < nv && q < nv;
369	            if nontrivial {
370	                o.push_str(&format!(
371	                    "  base {}: winding r = {} (a ROTAT period of {} mod {}, from a leaper crossing)\n",
372	                    a, r, a, nv
373	                ));
374	                o.push_str(&format!(
375	                    "  winding fixed as its native numeral (⊡ immutable_record): {}\n",
376	                    native_encode(&r.to_str_radix(10))
377	                ));
378	                o.push_str(&format!(
379	                    "  ⊡ ZWIND holonomy: ∮ A = 2π·{}, the integer winding of the orbit loop\n",
380	                    r
381	                ));
382	                let (lo, hi) = if p <= q { (p, q) } else { (q, p) };
383	                o.push_str(&format!(
384	                    "  a^(r/2) ± 1 splits it: {} = {} × {}   read off the winding, no table",
385	                    nv, lo, hi
386	                ));
387	                return o;
388	            }
389	            break;
390	        }
391	    }
392	    if budget_hit {
393	        o.push_str(&format!(
394	            "  no leaper crossing within the walk budget; hand to `trilattice_factor factor {}`",
395	            n
396	        ));
397	    } else {
398	        o.push_str(&format!(
399	            "  no base in the set gave an even winding with a non-trivial split; hand to `trilattice_factor factor {}`",
400	            n
401	        ));
402	    }
403	    o
404	}
