406	/// The default smoothness bound for the winding-bridge route.
407	const BRIDGE_BOUND: u64 = 300_000;
408	
409	/// The winding-bridge, the ⊞/⊡ decomposition past the order ceiling. When one
410	/// factor p has a smooth winding, meaning p-1 has only small prime factors, the
411	/// accumulated winding M = product of e for e up to the bound is a multiple of
412	/// p-1, so a^M ≡ 1 mod p while a^M is generic mod the other factor. That is the
413	/// MOAT_BRIDGE_TYPE mismatch: the winding bridges to p and stays across the moat
414	/// to q. gcd(a^M - 1, n) reads the bridged factor out. This never touches the
415	/// order's size, so it breaks the sqrt-order ceiling for a smooth-winding
416	/// factor; it finds nothing when both factors' windings are non-smooth, which
417	/// is the case an RSA modulus is chosen to be. This is Pollard's p-1.
418	fn winding_bridge(n: &BigUint, bound: u64) -> Option<BigUint> {
419	    let one = BigUint::one();
420	    let two = BigUint::from(2u32);
421	    let mut a = two % n;
422	    let mut e: u64 = 2;
423	    // Check the gcd at every step. The first factor whose winding divides the
424	    // accumulated M sends a to 1 mod that factor while it is still generic mod
425	    // the other, so gcd(a-1, n) crosses to it. Checking only in coarse batches
426	    // can let the second factor bridge inside the same batch, collapsing the
427	    // gcd to n and losing the split; per-step checking catches the first
428	    // crossing exactly. Cost stays dominated by the modular power, not the gcd.
429	    while e <= bound {
430	        a = a.modpow(&BigUint::from(e), n);
431	        e += 1;
432	        if a.is_zero() || a == one { break; } // bridged out or collapsed; no readable split
433	        let g = big_gcd(&a - &one, n.clone());
434	        if g > one && &g < n { return Some(g); }
435	    }
436	    None
437	}
