439	/// The bridge subcommand: factor n by the winding-bridge (Pollard p-1) at the
440	/// given smoothness bound, reading the split off the bridged winding.
441	pub fn bridge(n: &str, bound_opt: Option<u64>) -> String {
442	    let bound = bound_opt.unwrap_or(BRIDGE_BOUND);
443	    let nv: BigUint = match n.trim().parse() {
444	        Ok(v) => v,
445	        Err(_) => return format!("trilattice_factor bridge {}: not a non-negative integer", n),
446	    };
447	    let two = BigUint::from(2u32);
448	    if nv < two {
449	        return format!("trilattice_factor bridge {}: n < 2, nothing to bridge", n);
450	    }
451	    let mut o = format!("trilattice_factor bridge {}:\n", n);
452	    match winding_bridge(&nv, bound) {
453	        Some(g) => {
454	            let cof = &nv / &g;
455	            let (lo, hi) = if g <= cof { (g, cof) } else { (cof, g) };
456	            o.push_str(&format!(
457	                "  ⊞ MOAT_BRIDGE_TYPE: one factor's winding is {}-smooth, the other is not\n",
458	                bound
459	            ));
460	            o.push_str(&format!(
461	                "  ⊡ WIND_BRIDGE: gcd(a^M - 1, n) crosses to the bridged factor\n"
462	            ));
463	            o.push_str(&format!("  {} = {} × {}   read off the winding-bridge", nv, lo, hi));
464	        }
465	        None => o.push_str(&format!(
466	            "  no factor with a {}-smooth winding at this bound; raise the bound or hand to `trilattice_factor factor {}`",
467	            bound, n
468	        )),
469	    }
470	    o
471	}
472	
473	/// The bridge-of-comparable-size, the ∈ BRIDGE_EXIST decomposition. The
474	/// fragment ∃y∈x(|y|∼|x|) is a factor of the same magnitude as sqrt(n): write
475	/// n = a^2 - b^2 = (a-b)(a+b), the congruence of squares. Walk a up from
476	/// ceil(sqrt n) until a^2 - n is itself a square b^2; then a-b and a+b are the
477	/// two comparable factors. The step count is a - sqrt(n), small when the two
478	/// factors are close and growing as they spread.
479	///
480	/// No arbitrary step cap: the walk self-terminates. Every odd composite n = p·q
481	/// has a valid a = (p+q)/2, no larger than (n+1)/2, so a walk that reaches
482	/// (n+1)/2 without a split means n has none, which for an odd number means it is
483	/// prime. Callers guard with a primality test first, so this only ever runs on a
484	/// composite and always returns a factor; the natural bound is a safety, not a
485	/// budget. It is slow when the factors are far apart, which is the case rho
486	/// handles, so a caller wanting speed on an unbalanced n reaches for `factor`.
487	fn difference_of_squares(n: &BigUint) -> Option<(BigUint, BigUint)> {
488	    let one = BigUint::one();
489	    let two = BigUint::from(2u32);
490	    let limit = (n + &one) / &two; // a > this means no factorization remains
491	    let mut a = n.sqrt();
492	    if &a * &a < *n { a += &one; } // ceil(sqrt n)
493	    while a <= limit {
494	        let a2 = &a * &a;
495	        let b2 = &a2 - n;
496	        let b = b2.sqrt();
497	        if &b * &b == b2 {
498	            let lo = &a - &b;
499	            let hi = &a + &b;
500	            if lo > one && lo < *n { return Some((lo, hi)); }
501	        }
502	        a += &one;
503	    }
504	    None
505	}
506	
507	/// The squares subcommand: factor n by the difference-of-squares bridge,
508	/// reading the split off two factors of comparable size (∈ BRIDGE_EXIST).
509	pub fn squares(n: &str) -> String {
510	    let nv: BigUint = match n.trim().parse() {
511	        Ok(v) => v,
512	        Err(_) => return format!("trilattice_factor squares {}: not a non-negative integer", n),
513	    };
514	    let two = BigUint::from(2u32);
515	    if nv < BigUint::from(3u32) {
516	        return format!("trilattice_factor squares {}: n < 3, nothing to bridge", n);
517	    }
518	    if (&nv % &two).is_zero() {
519	        return format!(
520	            "trilattice_factor squares {}: {} = 2 × {}   (even; the squares bridge is for odd n)",
521	            n, nv, &nv / &two
522	        );
523	    }
524	    // The walk self-terminates only at (n+1)/2, which is unreachable for a large
525	    // prime, so rule primes out first with the real primality test.
526	    if crate::prime_winding::is_prime(&nv.to_str_radix(10)) == crate::prime_winding::PrimeVerdict::Prime {
527	        return format!("trilattice_factor squares {}: {} is prime, no difference of squares", n, nv);
528	    }
529	    let mut o = format!("trilattice_factor squares {}:\n", n);
530	    match difference_of_squares(&nv) {
531	        Some((lo, hi)) => {
532	            o.push_str("  ∈ BRIDGE_EXIST: a bridge of comparable size, |y| ∼ |x| ∼ √n\n");
533	            o.push_str("  ⊙ n = a² - b² = (a-b)(a+b), the congruence of squares\n");
534	            o.push_str(&format!("  {} = {} × {}   read off the difference of squares", nv, lo, hi));
535	        }
536	        None => o.push_str(&format!(
537	            "  no non-trivial difference of squares below (n+1)/2; hand to `trilattice_factor factor {}`",
538	            n
539	        )),
540	    }
541	    o
542	}
543	
544	/// The default factor-base bound for the congruence route.
545	const CONGRUENCE_FB_BOUND: u64 = 2000;
546	/// How many trials the congruence route draws before giving up.
547	const CONGRUENCE_TRIALS: u64 = 4_000_000;
548	
549	/// Primes up to `bound`, the fixed alphabet (⊣ factor base) a relation must
550	/// factor over to be admitted.
551	fn factor_base(bound: u64) -> alloc::vec::Vec<u64> {
552	    let mut sieve = alloc::vec![true; (bound as usize) + 1];
553	    let mut ps = alloc::vec::Vec::new();
554	    let mut p = 2u64;
555	    while p <= bound {
556	        if sieve[p as usize] {
557	            ps.push(p);
558	            let mut m = p * p;
559	            while m <= bound { sieve[m as usize] = false; m += p; }
560	        }
561	        p += 1;
562	    }
563	    ps
564	}
565	
566	/// Factor `q` over the base, returning the exponent of each base prime, or None
567	/// if `q` does not reduce to 1 over the base (not smooth). This is the ∈
568	/// smoothness gate: only a relation that factors entirely over the alphabet is
569	/// admitted, the rest discarded (≺).
570	fn smooth_exponents(mut q: BigUint, fb: &[u64]) -> Option<alloc::vec::Vec<u32>> {
571	    let mut exps = alloc::vec![0u32; fb.len()];
572	    let zero = BigUint::zero();
573	    for (i, &p) in fb.iter().enumerate() {
574	        let bp = BigUint::from(p);
575	        while (&q % &bp) == zero {
576	            q /= &bp;
577	            exps[i] += 1;
578	        }
579	    }
580	    if q == BigUint::one() { Some(exps) } else { None }
581	}
582	
583	/// The congruence-of-squares split, the sub-exponential route from the ob3ect
584	/// `square_congruence_from_smooth_relations` (word ⊢⊣≻∈⊥≺⊤⋈⋈∈⊞≻≻⊙∈⊤⊥∋⊡⊣). It
585	/// never touches the order, so it reaches the balanced hard semiprime the order
586	/// routes cannot. ⊣ fixes the factor base; ≻ generates a trial x and q = x² mod
587	/// n; ∈ is the smoothness branch, ≺ discards a non-smooth trial, ⊤ accepts a
588	/// smooth one; ⋈ accumulates its exponent-parity row. ⊞ is the parity
589	/// cancellation: once there are more rows than base primes, some combination
590	/// sums to all-even by counting alone, guaranteed. ⊙ is the square that
591	/// combination forms on both sides; ∋ resolves it to X² ≡ Y² (mod n); ⊥ throws
592	/// back a trivial pair X ≡ ±Y; ⊡ records the split gcd(X - Y, n).
593	fn congruence_split(n: &BigUint, fb_bound: u64, trials: u64) -> Option<(BigUint, BigUint)> {
594	    use alloc::vec::Vec;
595	    let one = BigUint::one();
596	    let fb = factor_base(fb_bound);
597	    let k = fb.len();
598	
599	    // Collected smooth relations: (x, full exponents).
600	    let mut rel_x: Vec<BigUint> = Vec::new();
601	    let mut rel_e: Vec<Vec<u32>> = Vec::new();
602	    // GF(2) reducers: each carries a parity bitmask and the set of relation ids
603	    // that XOR to it, both as bit-vectors, keyed for elimination by leading bit.
604	    let bits = (k + 64) / 64;
605	    let mut red: Vec<(Vec<u64>, Vec<u64>, usize)> = Vec::new(); // (parity, combo, leadbit)
606	
607	    let getbit = |v: &[u64], i: usize| -> bool { (v[i >> 6] >> (i & 63)) & 1 == 1 };
608	    let setbit = |v: &mut [u64], i: usize| { v[i >> 6] |= 1 << (i & 63); };
609	
610	    let mut seed: u64 = 0x1234_5678_9ABC_DEF1 ^ (n.to_u64_digits().first().copied().unwrap_or(1));
611	    let nsqrt = n.sqrt();
612	
613	    let mut t: u64 = 0;
614	    while t < trials {
615	        t += 1;
616	        // Trial x drawn above sqrt(n) so q = x² - n stays smaller than n.
617	        seed ^= seed << 13; seed ^= seed >> 7; seed ^= seed << 17;
618	        let off = BigUint::from(seed % 1_000_000_007);
619	        let x = (&nsqrt + &off) % n;
620	        if x < BigUint::from(2u32) { continue; }
621	        let q = (&x * &x) % n;
622	        if q == BigUint::zero() {
623	            // x shares a factor with n outright.
624	            let g = big_gcd(x.clone(), n.clone());
625	            if g > one && &g < n { return Some((g.clone(), n / &g)); }
626	            continue;
627	        }
628	        let exps = match smooth_exponents(q.clone(), &fb) { Some(e) => e, None => continue };
629	
630	        // Parity row over the base.
631	        let mut par = alloc::vec![0u64; bits];
632	        for (i, e) in exps.iter().enumerate() { if e & 1 == 1 { setbit(&mut par, i); } }
633	
634	        let id = rel_x.len();
635	        rel_x.push(x);
636	        rel_e.push(exps);
637	        let mut combo = alloc::vec![0u64; (rel_x.len() + 64) / 64];
638	        // combo may need to grow as ids accumulate; size it generously below.
639	        if combo.len() * 64 <= id { combo.push(0); }
640	        setbit(&mut combo, id);
641	
642	        // Reduce the new row by existing reducers.
643	        for (rpar, rcombo, lead) in red.iter() {
644	            if getbit(&par, *lead) {
645	                for w in 0..bits { par[w] ^= rpar[w]; }
646	                while combo.len() < rcombo.len() { combo.push(0); }
647	                for w in 0..rcombo.len() { combo[w] ^= rcombo[w]; }
648	            }
649	        }
650	
651	        // Zero parity → a dependency: the combo is a set of relations whose
652	        // exponent sums are all even, a square on both sides.
653	        let is_zero = par.iter().all(|&w| w == 0);
654	        if is_zero {
655	            // Build X = prod x_i mod n, and Y from halved summed exponents.
656	            let mut sum = alloc::vec![0u32; k];
657	            let mut xprod = one.clone();
658	            for cid in 0..rel_x.len() {
659	                if getbit(&combo, cid) {
660	                    xprod = (&xprod * &rel_x[cid]) % n;
661	                    for i in 0..k { sum[i] += rel_e[cid][i]; }
662	                }
663	            }
664	            let mut yprod = one.clone();
665	            for i in 0..k {
666	                if sum[i] > 0 {
667	                    let half = sum[i] / 2;
668	                    yprod = (&yprod * BigUint::from(fb[i]).modpow(&BigUint::from(half), n)) % n;
669	                }
670	            }
671	            // gcd(X - Y, n): a non-trivial common part splits n.
672	            let diff = if xprod >= yprod { &xprod - &yprod } else { (n + &xprod) - &yprod };
673	            let g = big_gcd(diff % n, n.clone());
674	            if g > one && &g < n { return Some((g.clone(), n / &g)); }
675	            // Trivial (X ≡ ±Y): keep collecting for another dependency.
676	        } else {
677	            let lead = {
678	                let mut hb = 0usize;
679	                for i in 0..k { if getbit(&par, i) { hb = i; } }
680	                hb
681	            };
682	            red.push((par, combo, lead));
683	        }
684	    }
685	    None
686	}
687	
688	/// The sieve subcommand: factor n by the congruence of squares over a factor
689	/// base of primes up to B, reading the split off a parity cancellation.
690	pub fn sieve(n: &str, b_opt: Option<u64>) -> String {
691	    let bound = b_opt.unwrap_or(CONGRUENCE_FB_BOUND);
692	    let nv: BigUint = match n.trim().parse() {
693	        Ok(v) => v,
694	        Err(_) => return format!("trilattice_factor sieve {}: not a non-negative integer", n),
695	    };
696	    if nv < BigUint::from(3u32) {
697	        return format!("trilattice_factor sieve {}: n < 3, nothing to split", n);
698	    }
699	    if crate::prime_winding::is_prime(&nv.to_str_radix(10)) == crate::prime_winding::PrimeVerdict::Prime {
700	        return format!("trilattice_factor sieve {}: {} is prime, no congruence to build", n, nv);
701	    }
702	    let mut o = format!("trilattice_factor sieve {}:\n", n);
703	    match congruence_split(&nv, bound, CONGRUENCE_TRIALS) {
704	        Some((lo, hi)) => {
705	            let (lo, hi) = if lo <= hi { (lo, hi) } else { (hi, lo) };
706	            o.push_str(&format!("  ⊣ factor base: primes up to {}\n", bound));
707	            o.push_str("  ⊞ parity cancellation: smooth rows summed to an all-even square on both sides\n");
708	            o.push_str("  ⊙ X² ≡ Y² (mod n); ⊡ gcd(X - Y, n) crosses to the factor\n");
709	            o.push_str(&format!("  {} = {} × {}   read off the congruence of squares", nv, lo, hi));
710	        }
711	        None => o.push_str(&format!(
712	            "  no non-trivial congruence at base bound {} within the trial budget; raise the bound or hand to `trilattice_factor factor {}`",
713	            bound, n
714	        )),
715	    }
716	    o
717	}
718	
719	/// Factor n, leading with the trilattice reading and then the real divisor
720	/// search from `prime_winding` (one copy of the arithmetic, called here).
721	pub fn factor(n: &str, max_power: Option<u64>) -> String {
722	    let mut o = String::new();
723	    o.push_str(&read(n));
724	    o.push('\n');
725	    o.push_str(&factor_bounded(n, max_power));
726	    o
727	}
