    u64 val = powm(a, start - 1, n);       // a^(start-1); start>=1 so no underflow
    for (u64 r=start; r<end; r++){
        val = mulm(val, a, n);             // val = a^r
        if (val == 1){ atomicMin(result, r); return; }
    }
}
"#;

