fn pow_mod_u64(a: u64, mut e: u64, n: u64) -> u64 {
    if n == 1 { return 0; }
    let mut r: u128 = 1 % n as u128;
    let mut ab: u128 = (a % n) as u128;
    while e > 0 {
        if e & 1 == 1 { r = (r * ab) % n as u128; }
        ab = (ab * ab) % n as u128;
        e >>= 1;
    }
    r as u64
