    let mut d_giant = stream.clone_htod(&zeros).ok()?;
    let mut gb = stream.launch_builder(&giant_fn);
    gb.arg(&g); gb.arg(&n); gb.arg(&m); gb.arg(&mut d_giant);
    unsafe { gb.launch(cfg) }.ok()?;
