58	/// Convert N (decimal string) to hex, then concatenate each nibble's
59	/// canonical word, most-significant nibble first.
60	pub fn digit_encode(n_str: &str) -> String {
61	    let n: BigUint = match trim(n_str).parse() { Ok(v) => v, Err(_) => return String::new() };
62	    let hex = n.to_str_radix(16);
63	    let mut out = String::new();
64	    for c in hex.chars() {
65	        if let Some(d) = c.to_digit(16) {
66	            out.push_str(HEX_WORDS[d as usize]);
67	        }
68	    }
69	    out
70	}
