231	// ── Output formatters ───────────────────────────────────────────────────────
232	
233	pub fn word() -> String {
234	    format!(
235	        "prime_winding word: {}\n  period: {}\n  glyphs: {} (12 opcodes + 2 anchors)",
236	        WORD, PERIOD, WORD.chars().count()
237	    )
238	}
