240	/// Find the nearest prime ≤ n. n is a decimal string (arbitrary precision).
241	/// Stops the moment the search meets an Undetermined verdict — it does
242	/// not step past a number outside its reach.
243	///
244	/// The verdict depends on every digit, so there is no way to jump to the
245	/// answer; decrementing one at a time is the search itself. `SCAN_CAP` bounds
246	/// the step count at a value measured to stay interactive; past that it
247	/// reports OutOfReach, stating what was scanned rather than hanging.
248	pub fn find(n: &str) -> String {
249	    if lt(n, "2") {
250	        return format!("prime_winding find {}: no primes ≤ {}", n, n);
251	    }
252	    let start = trim(n);
253	    let mut m = start.clone();
254	    let mut steps: u64 = 0;
255	    loop {
256	        match is_prime(&m) {
257	            PrimeVerdict::Prime => {
258	                let glyph = digit_encode(&m);
259	                return if m == start {
260	                    format!("prime_winding find {}: {} IS PRIME\n  glyph: {}", n, n, glyph)
261	                } else {
262	                    format!(
263	                        "prime_winding find {}: {} is composite, nearest prime ≤ {} is {}\n  glyph: {}",
264	                        n, n, n, m, glyph
265	                    )
266	                };
267	            }
268	            PrimeVerdict::Undetermined => {
269	                return format!(
270	                    "prime_winding find {}: {} is vacuous on its digit-encoded word — no clear ever fired, cannot certify further",
271	                    n, m
272	                );
273	            }
274	            PrimeVerdict::Composite => {}
275	        }
276	        if lt(&m, "2") {
277	            return format!("prime_winding find {}: no prime found below", n);
278	        }
279	        m = sub(&m, "1");
280	        steps += 1;
281	        if steps > SCAN_CAP {
282	            return format!(
283	                "prime_winding find {}: OutOfReach — {} step(s) scanned below {} with no closing or vacuous word, scan halted at {}",
284	                n, steps, n, m
285	            );
286	        }
287	    }
288	}
289	
290	/// Enumerate every prime in [lo, hi], high to low, as the find/subtract/repeat
291	/// walk: test the current value, on a prime record it and drop to prime-1, on a
292	/// composite drop by one, until below lo. One primality test per integer, no
293	/// table, so it runs at arbitrary precision and around an arbitrarily large
294	/// starting point where a sieve cannot allocate. For a dense low range a sieve
295	/// is faster; this is for reach and for zero memory, not for beating a sieve.
296	///
297	/// `count_only` suppresses the per-prime listing and returns only the tally,
298	/// for spans too wide to print.
299	pub fn range(lo: &str, hi: &str, count_only: bool) -> String {
300	    let lo_t = trim(lo);
301	    let hi_t = trim(hi);
302	    if lt(&hi_t, &lo_t) {
303	        return format!("prime_winding range [{}, {}]: empty span (hi < lo)", lo, hi);
304	    }
305	    let mut m = hi_t.clone();
306	    let mut count: u64 = 0;
307	    let mut tested: u64 = 0;
308	    let mut listing = String::new();
309	    loop {
310	        if lt(&m, &lo_t) || lt(&m, "2") { break; }
311	        tested += 1;
312	        if let PrimeVerdict::Prime = is_prime(&m) {
313	            count += 1;
314	            if !count_only {
315	                listing.push_str(&m);
316	                listing.push('\n');
317	            }
318	        }
319	        if m == "2" { break; }
320	        m = sub(&m, "1");
321	    }
322	    if count_only {
323	        format!("prime_winding range [{}, {}]: {} prime(s) ({} integers tested)", lo, hi, count, tested)
324	    } else {
325	        format!("prime_winding range [{}, {}]: {} prime(s)\n{}", lo, hi, count, listing)
326	    }
327	}
328	
329	/// a / b, both nonzero, Euclid's algorithm on BigUint. Public so the
330	/// trilattice winding route reads the same gcd rather than carrying its own.
331	pub fn big_gcd(mut a: BigUint, mut b: BigUint) -> BigUint {
332	    while !b.is_zero() {
333	        let t = b.clone();
334	        b = &a % &b;
335	        a = t;
336	    }
337	    a
338	}
339	
340	/// Brent's polynomial x -> x^2 + c mod n.
341	fn brent_f(x: &BigUint, c: &BigUint, n: &BigUint) -> BigUint {
342	    let x2 = (x * x) % n;
343	    (&x2 + c) % n
344	}
345	
346	/// One Brent's-rho walk with a fixed (c, x0) seed. Returns a nontrivial
347	/// factor of n if the walk crosses one within max_power steps, None
348	/// otherwise. This has no guaranteed success bound -- that is Brent's
349	/// rho's real, known shape, not a defect to hide -- so a walk that
350	/// exhausts its steps reports None plainly rather than assuming n is
351	/// prime because this one seed failed to split it.
352	///
353	/// x is the tortoise, fixed for the whole doubling round r; y is the hare,
354	/// walked r steps ahead of x and compared against it in batches of m,
355	/// accumulating the product of differences mod n so one gcd covers the
356	/// whole batch. A batch gcd landing on n itself (the product folded in
357	/// more than one factor's collision at once) is not a dead end -- it is
358	/// recovered by re-walking that same batch from its start (`ys`) one step
359	/// at a time, gcd on each step, until the exact collision point splits
360	/// out the real factor.
361	fn brent_walk(n: &BigUint, c: u64, x0: u64, max_power: u64) -> Option<BigUint> {
362	    let c = BigUint::from(c);
363	    let one = BigUint::one();
364	    let mut x = BigUint::from(x0);
365	    let mut y = x.clone();
366	    let m: u64 = 128;
367	    let mut r: u64 = 1;
368	    let mut g = one.clone();
369	    let mut q = one.clone();
370	    let mut ys = y.clone();
371	
372	    while g.is_one() && r < max_power {
373	        x = y.clone();
374	        for _ in 0..r {
375	            y = brent_f(&y, &c, n);
376	        }
377	        let mut k: u64 = 0;
378	        while k < r && g.is_one() {
379	            ys = y.clone();
380	            let steps = m.min(r - k);
381	            for _ in 0..steps {
382	                y = brent_f(&y, &c, n);
383	                let diff = if y > x { &y - &x } else { &x - &y };
384	                q = (&q * diff) % n;
385	            }
386	            g = big_gcd(q.clone(), n.clone());
387	            k += m;
388	        }
389	        r = match r.checked_mul(2) { Some(v) => v, None => break };
390	    }
391	
392	    if &g == n {
393	        loop {
394	            ys = brent_f(&ys, &c, n);
395	            let diff = if ys > x { &ys - &x } else { &x - &ys };
396	            g = big_gcd(diff, n.clone());
397	            if !g.is_one() { break; }
398	        }
399	    }
400	
401	    if !g.is_one() && &g != n { Some(g) } else { None }
402	}
403	
404	/// The seeds a Brent's-rho split tries, each its own independent walk on
405	/// the same n -- distinct starting strands over the same braid, any one
406	/// of which closing (finding a nontrivial gcd) splits n. Hosted runs all
407	/// of them at once, one thread per strand, the way `live_hud` already
408	/// runs a background thread in this same binary; bare metal, with no
409	/// std::thread, walks them one at a time. Same seeds, same walk, same
410	/// answer either way -- only whether the strands run concurrently
411	/// differs.
412	const BRENT_SEEDS: [(u64, u64); 6] = [(3, 2), (7, 5), (11, 3), (17, 7), (23, 11), (41, 13)];
413	const BRENT_MAX_POWER: u64 = 4_000_000;
414	
415	#[cfg(feature = "hosted")]
416	fn brent_split_one(n: &BigUint, max_power: u64) -> Option<BigUint> {
417	    use std::sync::mpsc;
418	    use std::thread;
419	    let (tx, rx) = mpsc::channel();
420	    for &(c, x0) in BRENT_SEEDS.iter() {
421	        let n = n.clone();
422	        let tx = tx.clone();
423	        thread::spawn(move || {
424	            if let Some(f) = brent_walk(&n, c, x0, max_power) {
425	                let _ = tx.send(f);
426	            }
427	            // Un-joined on purpose: this walk is step-bounded so it always
428	            // terminates on its own; only the first strand to close matters,
429	            // and the losing strands finishing quietly in the background
430	            // costs nothing this tool needs to wait on.
431	        });
432	    }
433	    drop(tx);
434	    rx.recv().ok()
435	}
436	
437	#[cfg(not(feature = "hosted"))]
438	fn brent_split_one(n: &BigUint, max_power: u64) -> Option<BigUint> {
439	    for &(c, x0) in BRENT_SEEDS.iter() {
440	        if let Some(f) = brent_walk(n, c, x0, max_power) {
441	            return Some(f);
442	        }
443	    }
444	    None
445	}
446	
447	/// Recursively split n via Brent's rho until every piece is prime-confirmed
448	/// (`is_prime`, real Miller-Rabin) or a piece resists every seed within its
449	/// step bound. The latter is pushed to `unsplit` and reported as exactly
450	/// that -- a known composite this search did not finish factoring -- never
451	/// silently folded into `primes`.
452	fn brent_split_recursive(n: BigUint, primes: &mut Vec<BigUint>, unsplit: &mut Vec<BigUint>,
453	                          max_power: u64) {
454	    let mut stack: Vec<BigUint> = Vec::new();
455	    stack.push(n);
456	    while let Some(m) = stack.pop() {
457	        if m.is_one() { continue; }
458	        if is_prime(&m.to_str_radix(10)) == PrimeVerdict::Prime {
459	            primes.push(m);
460	            continue;
461	        }
462	        match brent_split_one(&m, max_power) {
463	            Some(f) => {
464	                let g = &m / &f;
465	                stack.push(f);
466	                stack.push(g);
467	            }
468	            None => unsplit.push(m),
469	        }
470	    }
471	}
472	
473	/// Factor n (decimal string, arbitrary precision). Trial division to
474	/// `TRIAL_DIVISION_BOUND` finds every small factor exactly; whatever
475	/// remains past that bound goes to Brent's rho (parallel strands, see
476	/// `brent_split_one`), which reaches factors far beyond trial division's
477	/// practical range without needing to divide up to n's own square root.
478	/// This is real, unbounded-precision arithmetic throughout -- closure
479	/// alone never produces a divisor, so it plays no role in the search,
480	/// only in confirming each candidate's primality via `is_prime`.
481	///
482	/// `max_power` bounds each Brent seed's walk (see `brent_walk`); `None`
483	/// keeps the default `BRENT_MAX_POWER`. The bound is not optional in the
484	/// sense of removable: Brent's rho carries no guaranteed termination on a
485	/// genuinely hard composite, and without SOME cutoff a call on such an n
486	/// would run forever with no way to ever report `unsplit`. What's
487	/// adjustable is the size of that cutoff, not whether one exists.
488	pub fn factor(n: &str) -> String {
489	    factor_bounded(n, None)
490	}
491	
492	/// `factor`, with the per-seed Brent step bound made explicit rather than
493	/// silently defaulted, for a caller that wants to trade search depth
494	/// against wall-clock time on a case the default budget resists.
495	pub fn factor_bounded(n: &str, max_power: Option<u64>) -> String {
496	    let max_power = max_power.unwrap_or(BRENT_MAX_POWER);
497	    let t = trim(n);
498	    let n_big: BigUint = match t.parse() {
499	        Ok(v) => v,
500	        Err(_) => return format!("prime_winding factor {}: not a valid non-negative integer", n),
501	    };
502	    if n_big < BigUint::from(2u32) {
503	        return format!("prime_winding factor {}: n < 2, no prime factors", n);
504	    }
505	
506	    let mut primes: Vec<BigUint> = Vec::new();
507	    let mut unsplit: Vec<BigUint> = Vec::new();
508	
509	    let mut m = n_big;
510	    let mut d: u64 = 2;
511	    while d <= TRIAL_DIVISION_BOUND {
512	        let bd = BigUint::from(d);
513	        if &bd * &bd > m { break; }
514	        if &m % &bd == BigUint::zero() {
515	            while &m % &bd == BigUint::zero() {
516	                primes.push(bd.clone());
517	                m /= &bd;
518	            }
519	        }
520	        d += if d == 2 { 1 } else { 2 };
521	    }
522	
523	    if m > BigUint::one() {
524	        brent_split_recursive(m, &mut primes, &mut unsplit, max_power);
525	    }
526	
527	    primes.sort_unstable();
528	    unsplit.sort_unstable();
529	
530	    if unsplit.is_empty() && primes.len() == 1 && primes[0].to_str_radix(10) == trim(n) {
531	        return format!("prime_winding factor {}: {} IS PRIME", n, n);
532	    }
533	
534	    let mut out = format!("prime_winding factor {}: ", n);
535	    if !primes.is_empty() {
536	        let rep: Vec<String> = primes.iter().map(|p| p.to_str_radix(10)).collect();
537	        out.push_str(&format!("{} = {}", n, rep.join(" × ")));
538	    } else {
539	        out.push_str(&format!("{} — no confirmed prime factors", n));
540	    }
541	    if !unsplit.is_empty() {
542	        let rep: Vec<String> = unsplit.iter().map(|p| p.to_str_radix(10)).collect();
543	        out.push_str(&format!(
544	            "\n  └─ confirmed composite, not split by any of {} Brent seeds within {} steps each: {}",
545	            BRENT_SEEDS.len(), max_power, rep.join(" × ")
546	        ));
547	    }
548	    out
549	}
550	
551	pub fn cycle() -> String {
552	    let mut out = format!(
553	        "prime_winding cycle — ROTAT orbit of {}\n  period: {}\n  phase-bearing: {}\n  distinct landings: 4 (A, Ftf, tf, T)\n  landing register by cut:\n",
554	        WORD, PERIOD, PHASE_BEARING
555	    );
556	    for (i, land) in LANDINGS.iter().enumerate() {
557	        out.push_str(&format!("    k = {:>2}  {}\n", i, land));
558	    }
559	    out
560	}
561	
562	pub fn tuple() -> String {
563	    let slots = ["⊢", "⊣", "≻", "≺", "⋈", "⊤", "∈", "∋", "⊙", "⊥", "⊞", "⊡"];
564	    let mut out = String::from("prime_winding tuple (12 slots, ⊢→⊡):\n");
565	    for (i, slot) in slots.iter().enumerate() {
566	        if i < TUPLE.len() {
567	            out.push_str(&format!("  {}  {}\n", slot, TUPLE[i]));
568	        }
569	    }
570	    out
571	}
572	
573	pub fn verdict() -> String {
574	    String::from(
575	        "prime_winding verdict: T\n\
576	         μ∘δ = id holds on the word.\n\
577	         tri-ancestral: T — reconnection over a transformed object.\n\
578	         closed walk: false; verdict T over an open walk = reconnection without return.",
579	    )
580	}
581	
582	pub fn artifact() -> String {
583	    format!(
584	        "prime_winding artifact paths:\n  ob3ect json:   {}/{}_ob3ect.json\n  lean scaffold: {}/{}_scaffold.lean\n  diagram svg:   {}/{}_diagram_pen.svg",
585	        OB3ECT_DIR, ARTIFACT_SLUG, OB3ECT_DIR, ARTIFACT_SLUG, OB3ECT_DIR, ARTIFACT_SLUG
586	    )
587	}
588	
589	pub fn help() -> String {
590	    format!(
591	        "prime_winding — winding period of the primes on the number line\n\
592	         glyph word: {}\n\
593	         period: {}, phase-bearing, Frobenius verdict: {}\n\
594	         primality runs on a digit-to-glyph encoding: each digit 0-9 has\n\
595	         its own IMASM word, N's word is those concatenated in digit\n\
596	         order, and N is prime iff that word's banking already holds.\n\
597	         No step budget — linear in digit count, so arbitrary-length N\n\
598	         resolves the same way a small one does. factor walks small\n\
599	         trial divisors and reads each cofactor's status from this same\n\
600	         check.\n\n\
601	         subcommands:\n\
602	           prime_winding word       canonical glyph word\n\
603	           prime_winding find <n>   find nearest prime ≤ n (arbitrary precision)\n\
604	           prime_winding range <lo> <hi> [count]   every prime in [lo,hi], the find/subtract walk\n\
605	           prime_winding factor <n>  factor n into prime divisors (with multiplicity)\n\
606	           prime_winding cycle      ROTAT orbit with landing register per cut\n\
607	           prime_winding tuple      the 12-slot tuple the word was imscribed from\n\
608	           prime_winding verdict    Frobenius verdict and tri-ancestral reading\n\
609	           prime_winding artifact   ob3ect + Lean scaffold paths\n\
610	           prime_winding help       this help",
611	        WORD, PERIOD, FROBENIUS_VERDICT
612	    )
613	}
614	
615	pub fn prime_verdict_label(v: PrimeVerdict) -> &'static str { prime_verdict_str(v) }
