/// Divide by a divisor known to fit in one word, reading a's own limbs
/// from the most significant one down and carrying the running remainder
/// into the next limb -- the same technique any bignum library uses for
/// single-word division, genuinely limb-at-a-time rather than bit-at-a-
/// time. divmod_via_word's own bits_divmod walks every bit of the
/// dividend and allocates a fresh quotient bit vector on every call; that
/// generality is exactly what a hot loop trying thousands or millions of
/// small candidate divisors cannot afford, the same lesson the GPU BSGS
/// work already drew: a slow, allocation-heavy path computing the
/// identical value as a fast one is worth replacing with the fast shape,
/// not with abandoning word-native arithmetic for the loop. None for
/// small=0.
pub fn divmod_small_via_word(a: &BigUint, small: u64) -> Option<(BigUint, u64)> {
    if small == 0 { return None; }
    let limbs = word_bits(a);
    let mut q = alloc::vec::Vec::with_capacity(limbs.len());
    q.resize(limbs.len(), 0u64);
    let mut rem: u128 = 0;
    let divisor = small as u128;
    for i in (0..limbs.len()).rev() {
        let cur = (rem << 64) | limbs[i] as u128;
        q[i] = (cur / divisor) as u64;
        rem = cur % divisor;
    }
    Some((bits_to_value(&limbs_trim(q)), rem as u64))
}

/// The remainder half of divmod_small_via_word, for callers (trial
/// division's own divisibility check) that only need to know whether a
/// small divisor divides evenly, not the quotient.
pub fn modulo_small_via_word(a: &BigUint, small: u64) -> Option<u64> {
    divmod_small_via_word(a, small).map(|(_, r)| r)
}

