        use crate::native_numeral::{add_via_word, multiply_via_word};
        let mut acc = BigUint::zero();
        let mut pow = BigUint::one();
        for a in &self.f {
            acc = add_via_word(&acc, &multiply_via_word(a, &pow));
            pow = multiply_via_word(&pow, &self.m);
        }
        acc
    }

