            for _ in 0..(d - i) {
                term = multiply_via_word(&term, &bb);
            }
            let sign_neg = ((a < 0) && (i % 2 == 1)) ^ ((b < 0) && ((d - i) % 2 == 1));
            if sign_neg {
                neg = add_via_word(&neg, &term);
            } else {
                pos = add_via_word(&pos, &term);
            }
        }
        if pos >= neg {
            subtract_via_word(&pos, &neg).unwrap()
        } else {
            subtract_via_word(&neg, &pos).unwrap()
        }
    }

