fn ith_root(n: &BigUint, d: u32) -> BigUint {
    use crate::native_numeral::{add_via_word, divmod_small_via_word, divmod_via_word, multiply_via_word, pow2, subtract_via_word};
    assert!(d >= 1);
    if n.is_zero() || n.is_one() {
