            while pow_u32(&y, d) > *n {
                y = subtract_via_word(&y, &one).unwrap();
            }
            loop {
                let yp1 = add_via_word(&y, &one);
                if pow_u32(&yp1, d) > *n {
                    return y;
                }
                y = yp1;
            }
