fn pow_u32(base: &BigUint, exp: u32) -> BigUint {
    use crate::native_numeral::multiply_via_word;
    let mut acc = BigUint::one();
    let mut b = base.clone();
    let mut e = exp;
    while e > 0 {
        if e & 1 == 1 {
            acc = multiply_via_word(&acc, &b);
