/// Double a number, reading the result off its own word rather than
/// multiplying. See bits_double for the real operation.
pub fn double_via_word(n: &BigUint) -> BigUint {
    bits_to_value(&bits_double(&word_bits(n)))
}

/// Build the word a sequence of limbs (least-significant first, 64 bits
/// each) would have under encode, and decode it -- the one BigUint-exit
/// point every bits_* result passes through. Trailing zero bits beyond the
/// real value inside the top limb cost a few wasted ⊤ blocks at most and
/// decode reads them as the same value regardless.
pub(crate) fn bits_to_value(limbs: &[u64]) -> BigUint {
    if limbs.is_empty() { return BigUint::zero(); }
    let mut word = alloc::string::String::new();
    word.push('⊢');
    for &limb in limbs {
        for i in 0..64 {
            word.push('≻'); word.push('⋈'); word.push('∈');
            word.push(if (limb >> i) & 1 == 1 { '⊥' } else { '⊤' });
            word.push('∋');
        }
    }
    word.push('⊙'); word.push('⊡'); word.push('⊣');
    decode(&word).unwrap_or_else(BigUint::zero)
}

