// ─── crystal_scope.rs ──────────────────────────────────────────────────
// Primitive substitution microscope (build.txt, useful §crystal-scope).
//
// One diagnostic where three commands stood before: for a change to a 12-glyph
// tuple, report the distance, the tier transition, the entropy delta, the
// crystal-address jump, and WHICH PRIMITIVE DROVE IT.
//
// The driver is measured, not guessed. For each of the twelve axes it forms the
// tuple that differs from A in that axis alone and takes its distance under the
// same weighted metric the rest of the kernel uses. That marginal is the axis's
// actual contribution, so the largest one is the driver by construction rather
// than by intuition about which primitives "matter".
//
// Everything else is a lookup into machinery that already exists:
//   algebra::tuple_distance, algebra::primitive_mismatches   weighted + Hamming
//   cl8nk::tuple_distance_cl8nk                              graded conflicts
//   cl8nk::assess_tier -> entropy::Tier                      tier and S = ln N
//   IgTuple::crystal_address                                 gate-space address
#![allow(dead_code)]

extern crate alloc;
use alloc::format;
use alloc::string::{String, ToString};
use alloc::vec::Vec;

use crate::algebra::{primitive_mismatches, tuple_distance};
use crate::cl8nk::{assess_tier, tuple_distance_cl8nk};
use crate::entropy::Tier;
use crate::imas_ig::{IgPrim, IgTuple};

/// The twelve axes, in canonical order, with a getter and a setter each.
/// Written out rather than derived so the order is the catalog's order and
/// cannot drift from it silently.
const AXES: [&str; 12] = [
    "D", "T", "R", "P", "F", "K", "G", "C", "Phi", "H", "S", "Omega",
];

fn get_axis(t: &IgTuple, i: usize) -> IgPrim {
    match i {
        0 => t.d,
        1 => t.t,
        2 => t.r,
        3 => t.p,
        4 => t.f,
        5 => t.k,
        6 => t.g,
        7 => t.c,
        8 => t.phi,
        9 => t.h,
        10 => t.s,
        _ => t.omega,
    }
}

fn set_axis(t: &IgTuple, i: usize, v: IgPrim) -> IgTuple {
    let mut o = *t;
    match i {
        0 => o.d = v,
        1 => o.t = v,
        2 => o.r = v,
        3 => o.p = v,
        4 => o.f = v,
        5 => o.k = v,
        6 => o.g = v,
        7 => o.c = v,
        8 => o.phi = v,
        9 => o.h = v,
        10 => o.s = v,
        _ => o.omega = v,
    }
    o
}

/// Map the tier NAME onto the entropy tier, so S is a lookup and not a guess.
/// `cl8nk::assess_tier` and `entropy::Tier::name` already agree on these
/// strings; if they ever stop agreeing this returns None and the report says
/// the entropy is undetermined rather than inventing a number.
fn tier_of(t: &IgTuple) -> Option<Tier> {
    let name = assess_tier(t);
    Tier::all().into_iter().find(|x| x.name() == name)
}

pub struct AxisMove {
    pub axis: &'static str,
    pub from: IgPrim,
    pub to: IgPrim,
    /// Distance contributed by moving THIS axis alone.
    pub marginal: f32,
}

pub struct Scope {
    pub a: IgTuple,
    pub b: IgTuple,
    pub mismatches: u8,
    pub weighted: f32,
    pub cl8nk: f32,
    pub tier_a: Option<Tier>,
    pub tier_b: Option<Tier>,
    pub addr_a: u32,
    pub addr_b: u32,

// ─── Crystal Address Encoding ──────────────────────────────────
// Maps IgTuple → crystal address using the kernel's encode function.

impl IgTuple {
    /// Convert this IG tuple to 12 primitive indices (0-based within each family).
    /// Maps each IgPrim to its ordinal position within its primitive family.
    /// Convert this IG tuple to 12 primitive indices (0-based within each family).
    /// Uses catalog ordinal tables — no hardcoded match arms.
    /// Each index is the ordinal position of the primitive value within its family.
    pub fn to_crystal_indices(&self) -> [u8; 12] {
        use crate::catalog;
        [
            catalog::ord_index(&catalog::D_ORD, self.d).unwrap_or(0) as u8,
            catalog::ord_index(&catalog::T_ORD, self.t).unwrap_or(0) as u8,
            catalog::ord_index(&catalog::R_ORD, self.r).unwrap_or(0) as u8,
            catalog::ord_index(&catalog::P_ORD, self.p).unwrap_or(0) as u8,
            catalog::ord_index(&catalog::F_ORD, self.f).unwrap_or(0) as u8,
            catalog::ord_index(&catalog::K_ORD, self.k).unwrap_or(0) as u8,
            catalog::ord_index(&catalog::G_ORD, self.g).unwrap_or(0) as u8,
            catalog::ord_index(&catalog::C_ORD, self.c).unwrap_or(0) as u8,
            catalog::ord_index(&catalog::PHI_ORD, self.phi).unwrap_or(0) as u8,
            catalog::ord_index(&catalog::H_ORD, self.h).unwrap_or(0) as u8,
            catalog::ord_index(&catalog::S_ORD, self.s).unwrap_or(0) as u8,
            catalog::ord_index(&catalog::OMEGA_ORD, self.omega).unwrap_or(0) as u8,
        ]
    }

    /// Crystal address for this IG tuple.
    /// Uses the kernel's encode function from crystal.rs.
    pub fn crystal_address(&self) -> u32 {
        crate::crystal::encode(&self.to_crystal_indices())
    }

    /// Compute the theorem phases count from this tuple.
    /// Phases = sum of all 12 ordinal values, rounded to usize.
    /// This is the ONE-AND-ONLY source of the phases count —
    /// never hardcoded, always derived from the tuple.
    pub fn phases(&self) -> usize {
        let sum = self.d.ordinal() + self.t.ordinal() + self.r.ordinal() + self.p.ordinal()
                + self.f.ordinal() + self.k.ordinal() + self.g.ordinal() + self.c.ordinal()
                + self.phi.ordinal() + self.h.ordinal() + self.s.ordinal() + self.omega.ordinal();
        (sum + 0.5) as usize
    }
}

