mod kin_chi_probe {
    // A native_numeral word is a pure ⊤/⊥ (Kin/Chi) run, one glyph per bit
    // (native_numeral.rs:87). This probes whether varying that run's own
    // length and pattern moves the imscribed tuple at all, or whether
    // self_imscribe's composition collapses ⊤/⊥ sequences onto a small
    // fixed set of attractor states regardless of what bit pattern feeds
    // them in -- which is what the crystal-address collapse across very
    // different numbers (2, 10, 12345, 8051, 97, a 100-bit value all
    // landing on 16389838) would look like from the inside.
    use super::word_to_tuple;

    fn probe(label: &str, word: &str) {
        let ig = word_to_tuple(word);
        std::println!(
            "{label:>28}  len={:<4} {}  addr={}",
            word.chars().count(),
            super::glyphs(&ig),
            ig.crystal_address(),
        );
    }

    #[test]
    fn pure_kin_chi_runs_reported() {
        probe("single ⊤", "⊤");
        probe("single ⊥", "⊥");
        probe("⊤⊥", "⊤⊥");
        probe("⊥⊤", "⊥⊤");
        probe("⊤⊤", "⊤⊤");
        probe("⊥⊥", "⊥⊥");
        probe("⊤⊥ x4", "⊤⊥⊤⊥⊤⊥⊤⊥");
        probe("⊥⊤ x4", "⊥⊤⊥⊤⊥⊤⊥⊤");
        probe("⊤ x20", &"⊤".repeat(20));
        probe("⊥ x20", &"⊥".repeat(20));
        probe("⊤⊥ x20", &"⊤⊥".repeat(20));
        probe("⊤ x60", &"⊤".repeat(60));
        probe("⊥ x60", &"⊥".repeat(60));
        // native_numeral words for 2, 3, 10, 8051, 97 (bit=1→⊥, bit=0→⊤,
        // low bit first): 2=10 -> "⊤⊥", 3=11 -> "⊥⊥", 10=1010 -> "⊤⊥⊤⊥".
        probe("n=2 word", "⊤⊥");
        probe("n=3 word", "⊥⊥");
        probe("n=10 word", "⊤⊥⊤⊥");
    }
}

