        probe("⊥⊤ x4", "⊥⊤⊥⊤⊥⊤⊥⊤");
        probe("⊤ x20", &"⊤".repeat(20));
        probe("⊥ x20", &"⊥".repeat(20));
        probe("⊤⊥ x20", &"⊤⊥".repeat(20));
        probe("⊤ x60", &"⊤".repeat(60));
