        // low bit first): 2=10 -> "⊤⊥", 3=11 -> "⊥⊥", 10=1010 -> "⊤⊥⊤⊥".
        probe("n=2 word", "⊤⊥");
        probe("n=3 word", "⊥⊥");
        probe("n=10 word", "⊤⊥⊤⊥");
