/// N's own IgTuple built by TENSORING each hex digit's own imscription,
/// rather than running one concatenated word through self_imscribe as
/// digit_encode's word does. Concatenation makes one long program: past a
/// few nibbles, self_imscribe's period-gated axes (T,F,K,C,Phi,H, see
/// imas_ig.rs's from_snapshot_under doc) saturate on the same catch-all
/// bucket for every word, so almost every number's crystal address
/// collapses onto a small handful of states independent of its own digits
/// (measured directly: native_numeral words for 2, 10, 12345, 8051, 97,
/// and a 100-bit value all landed on the identical address 16389838).
/// Each HEX_WORDS[d] on its own is short enough never to hit that
/// saturation and is already verified pairwise distinct across all 16
/// against the kernel. Imscribing each digit alone, then composing those
/// 16 possible tuples with the lattice's own tensor (max/min per axis,
/// idempotent and commutative — algebra::tensor) instead of concatenating
/// programs, keeps every digit's own contribution live in the result.
pub fn digit_tensor_tuple(n_str: &str) -> Option<crate::imas_ig::IgTuple> {
    let n: BigUint = trim(n_str).parse().ok()?;
    let hex = n.to_str_radix(16);
    let mut acc: Option<crate::imas_ig::IgTuple> = None;
    for c in hex.chars() {
        let d = c.to_digit(16)? as usize;
        let digit_tuple = crate::axis_values::word_to_tuple(HEX_WORDS[d]);
        acc = Some(match acc {
            None => digit_tuple,
            Some(prev) => crate::algebra::tensor(&prev, &digit_tuple),
        });
    }
    acc
}

