#[test]
fn per_digit_types_are_pairwise_distinct() {
    // The whole tensor construction depends on this: if two different
    // hex digits imscribed to the SAME type, the composite could not
    // recover them distinctly either. Checked directly, not assumed.
    let mut types = alloc::vec::Vec::new();
    for w in HEX_WORDS.iter() {
        types.push(crate::axis_values::word_to_tuple(w).crystal_address());
    }
    for i in 0..16 {
        for j in (i + 1)..16 {
            assert_ne!(types[i], types[j], "hex digits {i:x} and {j:x} share a type");
        }
    }
}

