/// N's own composite TYPE, built by tensoring each hex digit's own crystal
/// address (its type — a point in the 17,280,000-point space crystal.rs
/// defines), not by combining IMASM tokens. Two things were tried and
/// rejected before this:
///   - running one concatenated word through self_imscribe (digit_encode's
///     own word): past a few nibbles this hits the period-gated axes'
///     saturation (imas_ig.rs's from_snapshot_under doc), collapsing almost
///     every N onto the same catch-all bucket regardless of its digits;
///   - tensoring the digits' own IgTuples with algebra::tensor: that stays
///     inside the SAME 12-mark space and is idempotent/commutative
///     (max/min per axis), so it is blind to repetition (10, 170, and
///     sixteen repeats of hex digit A all tensor to one result) and to
///     order (8051 and 8052 converge once their differing digit is
///     absorbed).
/// A tensor product does not fold inputs back into the space they came
/// from, it GROWS the space: n copies of a TOTAL-point space tensor into a
/// TOTAL^n-point space, the same way crystal.rs's own encode already
/// tensors twelve small axis spaces into the one 17,280,000-point space.
/// crystal::tensor_types does that one level up, over each digit's own
/// type (HEX_WORDS[d] is short enough never to hit self_imscribe's
/// saturation, and is already verified pairwise distinct across all 16).
/// The composite is injective in the digit sequence: order and repetition
/// both survive, and crystal::untensor_types recovers every digit's own
/// type back out exactly.
pub fn digit_type_tensor(n_str: &str) -> Option<alloc::vec::Vec<u8>> {
    let n: BigUint = trim(n_str).parse().ok()?;
    let hex = n.to_str_radix(16);
    let mut types: alloc::vec::Vec<u32> = alloc::vec::Vec::new();
    for c in hex.chars() {
        let d = c.to_digit(16)? as usize;
        let ty = crate::axis_values::word_to_tuple(HEX_WORDS[d]).crystal_address();
        types.push(ty);
    }
    Some(crate::crystal::tensor_types(&types))
}

