        if gcd != bgcd(ar[i].clone(), br[i].clone()) { bg+=1; }
    }
    format!("gpu_rho prims: {} cases -- montadd wrong {}, montsub wrong {}, gcd wrong {}", n, ba, bs, bg)
}

