167	pub fn verify_mont(limbs: usize, count: usize, device: usize) -> String {
168	    let ctx = match CudaContext::new(device) { Ok(c) => c, Err(e) => return format!("gpu_rho_ml: no ctx: {e}") };
169	    let stream = ctx.default_stream();
170	    let opts = CompileOptions { options: alloc::vec!["--device-int128".into()], ..Default::default() };
171	    let ptx = match compile_ptx_with_opts(kernel_src(limbs), opts) { Ok(p) => p, Err(e) => return format!("gpu_rho_ml: nvrtc: {e}") };
172	    let module = match ctx.load_module(ptx) { Ok(m) => m, Err(e) => return format!("gpu_rho_ml: module: {e}") };
173	    let func = match module.load_function("mont_verify_ml") { Ok(f) => f, Err(e) => return format!("gpu_rho_ml: load: {e}") };
174	
175	    let two_pow = BigUint::one() << (64 * limbs);
176	    let mut rng_state: u64 = 0x1234_5678 ^ (limbs as u64);
177	    let mut next = || { rng_state ^= rng_state << 13; rng_state ^= rng_state >> 7; rng_state ^= rng_state << 17; rng_state };
178	
179	    let (mut a_f, mut b_f, mut n_f, mut r2_f) = (Vec::new(), Vec::new(), Vec::new(), Vec::new());
180	    let mut n0s = Vec::with_capacity(count);
181	    let mut refs: Vec<BigUint> = Vec::with_capacity(count);
182	    for _ in 0..count {
183	        let mut nl: Vec<u64> = (0..limbs).map(|_| next()).collect();
184	        nl[limbs - 1] |= 1u64 << 63;
185	        nl[0] |= 1;
186	        let bn = from_limbs(&nl);
187	        let a = from_limbs(&(0..limbs).map(|_| next()).collect::<Vec<_>>()) % &bn;
188	        let b = from_limbs(&(0..limbs).map(|_| next()).collect::<Vec<_>>()) % &bn;
189	        let r2 = (&two_pow * &two_pow) % &bn;
190	        a_f.extend(limbs_of(&a, limbs));
191	        b_f.extend(limbs_of(&b, limbs));
192	        n_f.extend(nl.clone());
193	        r2_f.extend(limbs_of(&r2, limbs));
194	        n0s.push(n0_inv(nl[0]));
195	        refs.push((&a * &b) % &bn);
196	    }
197	
198	    let d_a = stream.clone_htod(&a_f).unwrap();
199	    let d_b = stream.clone_htod(&b_f).unwrap();
200	    let d_n = stream.clone_htod(&n_f).unwrap();
201	    let d_r2 = stream.clone_htod(&r2_f).unwrap();
202	    let d_n0 = stream.clone_htod(&n0s).unwrap();
203	    let mut d_out = stream.alloc_zeros::<u64>(count * limbs).unwrap();
204	    let block: u32 = 128;
205	    let grid = ((count as u32) + block - 1) / block;
206	    let cfg = LaunchConfig { grid_dim: (grid, 1, 1), block_dim: (block, 1, 1), shared_mem_bytes: 0 };
207	    let cc = count as u32;
208	    let mut b = stream.launch_builder(&func);
209	    b.arg(&d_a); b.arg(&d_b); b.arg(&d_n); b.arg(&d_r2); b.arg(&d_n0); b.arg(&mut d_out); b.arg(&cc);
210	    if let Err(e) = unsafe { b.launch(cfg) } { return format!("gpu_rho_ml: launch: {e}"); }
211	    let out = stream.clone_dtoh(&d_out).unwrap();
212	    let mut wrong = 0usize;
213	    for i in 0..count {
214	        let got = from_limbs(&out[i * limbs..i * limbs + limbs]);
215	        if got != refs[i] { wrong += 1; }
216	    }
217	    format!("gpu_rho_ml verify_mont: limbs={} count={} montmul wrong={}", limbs, count, wrong)
218	}
