355	/// Natural log of a positive BigUint via leading mantissa + bit length.
356	pub fn log_biguint(n: &BigUint) -> f64 {
357	    if n.is_zero() {
358	        return f64::NEG_INFINITY;
359	    }
360	    let bits = n.bits();
361	    let shift = bits.saturating_sub(53);
362	    let top = if shift == 0 {
363	        n.to_u64_digits().first().copied().unwrap_or(1)
364	    } else {
365	        (n >> shift).to_u64_digits().first().copied().unwrap_or(1)
366	    };
367	    (top as f64).ln() + (shift as f64) * core::f64::consts::LN_2
368	}
369	
370	/// Convert BigUint to u512 limbs (max 8 limbs = 512 bits, little-endian).
371	fn biguint_to_u512(n: &BigUint) -> [u64; 8] {
372	    let mut limbs = [0u64; 8];
373	    let digits = n.to_u64_digits();
374	    let nlimbs = digits.len().min(8);
375	    limbs[..nlimbs].copy_from_slice(&digits[..nlimbs]);
376	    limbs
377	}
