379	/// Number of limbs used in u512 (ignoring trailing zeros).
380	fn u512_nlimbs(limbs: &[u64; 8]) -> u32 {
381	    for i in (0..8).rev() {
382	        if limbs[i] != 0 {
383	            return i as u32 + 1;
384	        }
385	    }
386	    0
387	}
