396	fn inv_mod_u64(a: u64, p: u64) -> Option<u64> {
397	    if p < 2 || a % p == 0 {
398	        return None;
399	    }
400	    let mut t: i128 = 0;
401	    let mut newt: i128 = 1;
402	    let mut r: i128 = p as i128;
403	    let mut newr: i128 = (a % p) as i128;
404	    while newr != 0 {
405	        let q = r / newr;
406	        let (nt, nr) = (t - q * newt, r - q * newr);
407	        t = newt;
408	        newt = nt;
409	        r = newr;
410	        newr = nr;
411	    }
412	    if r > 1 {
413	        return None;
414	    }
415	    if t < 0 {
416	        t += p as i128;
417	    }
418	    Some(t as u64)
419	}
