421	fn eval_f_mod_u64(f: &[BigUint], x: u64, m: u64) -> u64 {
422	    if m < 2 {
423	        return 0;
424	    }
425	    let mm = m as u128;
426	    let mut acc: u128 = 0;
427	    let mut pow: u128 = 1;
428	    for a in f {
429	        let ai = big_mod_u64(a, m) as u128;
430	        acc = (acc + ai * pow) % mm;
431	        pow = (pow * x as u128) % mm;
432	    }
433	    acc as u64
434	}
