1	//! gpu_ecm.rs — Lenstra elliptic-curve factorization on the GPU, any width.
2	//!
3	//! One Montgomery curve per thread over a Montgomery field whose limb count is
4	//! chosen to fit N, so there is no size ceiling on the input. Each thread scales
5	//! its point by the product of prime powers up to B1 with the x-only ladder,
6	//! then takes gcd(Z, N); a curve whose order mod a factor p is B1-smooth drives
7	//! Z to 0 mod p and the gcd reveals p. Thousands of curves at once, first factor
8	//! wins. The arithmetic is verified against BigUint at each width before use.
9	
10	use alloc::format;
11	use alloc::string::String;
12	use alloc::vec::Vec;
13	use cudarc::driver::{CudaContext, LaunchConfig, PushKernelArg};
14	use cudarc::nvrtc::{compile_ptx_with_opts, CompileOptions, Ptx};
15	use num_bigint::BigUint;
16	use num_traits::{Zero, One};
17	use crate::gpu_rho::n0_inv;
18	
19	/// The ~250-line CIOS kernel had no PTX cache at all — every call to
20	/// factor_once/factor_once_bsgs/verify_width re-ran NVRTC from scratch on
21	/// the full source, which is why a 100-case verify at 4 limbs took minutes
22	/// instead of the near-instant runs gpu_rho_ml and gpu_gnfs already get
23	/// from caching. Same pattern as gpu_gnfs_fb.rs: hash the generated source
24	/// (it depends on `limbs`, so different widths get different cache files
25	/// automatically), load the cached PTX if present, else compile once and
26	/// write it out.
27	fn ptx_path(limbs: usize, src: &str) -> String {
28	    let mut h: u64 = 0xcbf29ce484222325;
29	    for &b in src.as_bytes() {
30	        h ^= b as u64;
31	        h = h.wrapping_mul(0x100000001b3);
32	    }
33	    format!("target/gpu_ecm_{limbs}_{h:016x}.ptx")
34	}
35	
36	fn load_ptx_cached(limbs: usize) -> Result<Ptx, String> {
37	    let src = kernel_src(limbs);
38	    let path = ptx_path(limbs, &src);
39	    if std::path::Path::new(&path).is_file() {
40	        return Ok(Ptx::from_file(&path));
41	    }
42	    let opts = CompileOptions { options: alloc::vec!["--device-int128".into()], ..Default::default() };
43	    let ptx = compile_ptx_with_opts(src, opts).map_err(|e| format!("NVRTC: {e}"))?;
