        .map(|i| {
            let mut h = alloc::vec![0u8; nrows];
            h[i] = 1;
            h
        })
        .collect();

    let mut row_i = 0usize;
    for col in 0..ncols {
        if row_i >= nrows {
            break;
        }
        let mut piv = None;
        for r in row_i..nrows {
            if (mat[r][col / 64] >> (col % 64)) & 1 == 1 {
                piv = Some(r);
                break;
            }
        }
        let Some(p) = piv else { continue };
        mat.swap(row_i, p);
        hist.swap(row_i, p);
        for r in 0..nrows {
            if r == row_i {
                continue;
            }
            if (mat[r][col / 64] >> (col % 64)) & 1 == 1 {
                for w in 0..words {
                    mat[r][w] ^= mat[row_i][w];
                }
                for k in 0..nrows {
                    hist[r][k] ^= hist[row_i][k];
                }
            }
        }
        row_i += 1;
    }

    for r in 0..nrows {
        if out.len() >= max_deps {
            break;
        }
        if !mat[r].iter().all(|&w| w == 0) {
            continue;
        }
        let idxs: Vec<usize> = hist[r]
            .iter()
            .enumerate()
            .filter_map(|(i, &b)| if b != 0 { Some(i) } else { None })
            .collect();
        if !idxs.is_empty() {
            out.push(idxs);
        }
    }

