fn try_gcd_host(x: &BigUint, y: &BigUint, n: &BigUint) -> Option<BigUint> {
    let candidates = [
        if x >= y { x - y } else { y - x },
        x + y,
        x.clone(),
        y.clone(),
    ];
    for c in candidates {
        if c.is_zero() {
            continue;
        }
        let g = big_gcd(c % n, n.clone());
        if g > BigUint::one() && &g < n {
            return Some(g);
        }
    }
    None
}

