56	/// Integer square root of a BigUint, capped at DIVISOR_REACH so the divisor
57	/// search stays inside the feasible, no-overflow range.
58	fn search_bound(n: &BigUint) -> u64 {
59	    // sqrt(n) via Newton on BigUint, then cap.
60	    if n < &BigUint::from(4u32) { return 2; }
61	    let mut x = n.clone();
62	    let mut y = (&x + 1u32) >> 1u32;
63	    while y < x { x = y.clone(); y = (&x + n / &x) >> 1u32; }
64	    // x = floor(sqrt(n))
65	    let cap = BigUint::from(DIVISOR_REACH);
66	    let b = if x > cap { cap } else { x };
67	    // to u64
68	    b.iter_u64_digits().next().unwrap_or(0)
69	}
