71	/// Smallest odd divisor of n in [3, bound], or None if none up to the bound.
72	fn smallest_odd_divisor(g: &Gpu, n: &BigUint, bound: u64) -> Result<Option<u64>, String> {
73	    if bound < 3 { return Ok(None); }
74	    let limbs: Vec<u32> = { let mut v = n.to_u32_digits(); if v.is_empty() { v.push(0); } v };
75	    let nlimbs = limbs.len() as u32;
76	    let d_limbs = g.stream.clone_htod(&limbs).map_err(|e| format!("gpu_factor: htod limbs: {e}"))?;
77	    const WIN: u64 = 1 << 22;
78	    let mut base: u64 = 3;
79	    while base <= bound {
80	        let span = (bound - base) / 2 + 1;
81	        let count = if span > WIN { WIN } else { span };
82	        let init: Vec<u64> = alloc::vec![u64::MAX];
83	        let mut d_res = g.stream.clone_htod(&init).map_err(|e| format!("gpu_factor: htod res: {e}"))?;
84	        let cfg = LaunchConfig::for_num_elems(count as u32);
85	        let mut b = g.stream.launch_builder(&g.func);
86	        b.arg(&d_limbs); b.arg(&nlimbs); b.arg(&base); b.arg(&count); b.arg(&mut d_res);
87	        unsafe { b.launch(cfg) }.map_err(|e| format!("gpu_factor: launch: {e}"))?;
88	        let res = g.stream.clone_dtoh(&d_res).map_err(|e| format!("gpu_factor: dtoh: {e}"))?;
89	        if res[0] != u64::MAX { return Ok(Some(res[0])); }
90	        base += 2 * count;
91	    }
92	    Ok(None)
93	}
