        Some((a, b)) => {
            let check = &a * &a + &b * &b;
            format!(
                "N = {}\n≻ i found: {}² ≡ -1 (mod N)\n≺ Cornacchia descent: a = {}, b = {}\n∋ a² + b² = {}  (checked = N: {})\nMiller-Rabin: N is {}.\nverdict: {}\n",
