/// a + b, computed the ordinary way (native_numeral::add_via_word already
/// carries this session's word-native pass), reported alongside all three
/// numbers' own real Grammar-native types -- each one sourced from
/// GROUNDED_HEX_DIGIT_TUPLES's real imscribe-generate grounding through
/// digit_type_tensor, not a bit read. The arithmetic and the type are two
/// separate questions answered separately: computing a+b correctly is
/// ordinary math, but a+b's own type is real self-referential Grammar
/// structure, not a byproduct of the sum. Reports whether the sum's type
/// equals either operand's own type outright (it can, since digit types
/// collapse hex digits 3≡7 and 4≡9 in this grounding run, already found and
/// left open rather than resolved), as a fact read off the real values, not
/// assumed from the arithmetic.
pub fn grounded_add_report(a_str: &str, b_str: &str) -> alloc::string::String {
    let a: BigUint = match trim(a_str).parse() {
        Ok(v) => v,
        Err(_) => return format!("grounded_add: '{}' is not a valid non-negative integer", a_str),
    };
    let b: BigUint = match trim(b_str).parse() {
        Ok(v) => v,
        Err(_) => return format!("grounded_add: '{}' is not a valid non-negative integer", b_str),
    };
    let sum = crate::native_numeral::add_via_word(&a, &b);
    let sum_str = sum.to_string();
    let ta = digit_type_address(a_str);
    let tb = digit_type_address(b_str);
    let ts = digit_type_address(&sum_str);
    format!(
        "{a} + {b} = {sum}\n  type({a}) = {}\n  type({b}) = {}\n  type({sum}) = {}\n  type(sum) == type(a): {}\n  type(sum) == type(b): {}\n",
        ta.as_deref().unwrap_or("(none)"),
        tb.as_deref().unwrap_or("(none)"),
        ts.as_deref().unwrap_or("(none)"),
        ts == ta,
        ts == tb,
    )
}

