        let rep: Vec<String> = unsplit.iter().map(|p| p.to_str_radix(10)).collect();
        out.push_str(&format!(
            "\n  └─ confirmed composite, not split by any of {} Brent seeds within {} steps each: {}",
            BRENT_SEEDS.len(), max_power, rep.join(" × ")
