    if !unsplit.is_empty() {
        let rep: Vec<String> = unsplit.iter().map(|p| p.to_str_radix(10)).collect();
        out.push_str(&format!("  (unsplit, confirmed composite: {})\n", rep.join(" × ")));
    }
    out
}

